basicstyle=\fontsize{7}{7}\ttfamily,
numbers=left,
firstnumber=1,
xleftmargin=5.0ex,
label={listing:core-melt},
caption={Core Meltdown.}, captionpos=b,]{core-meltdown.asm} 
