\[
  \inferrule[pc-commit-other]{Q = \textit{rl} \bullet Q^\prime \\ \robrdy_\textit{rl} \\ \neg\robexcp_\textit{rl} \\ \robmop_\textit{rl} \notin \{\texttt{mem-check}, \texttt{memi-check}, \texttt{mjge}, \texttt{mjg}, \texttt{mhalt} \} \\ \neg\halted}
  {\abracket{S, Q} \xtrans{\mpcc{\MAICM}} \abracket{[\pc \mapsto \pc \plusc 1]S, Q^\prime}}
\]

\[
  \inferrule[pc-commit-notrdy]{Q = \textit{rl} \bullet Q^\prime \\ \neg\robrdy_\textit{rl} \\ \neg\halted}
  {\abracket{S, Q} \xtrans{\mpcc{\MAICM}} \abracket{S, \emptyseq}}
\]

