\paragraph{\rob}

Since \MAICM\ is pipelined, it needs to deal with situations where the
contents of the pipeline must be invalidated as they correspond to
microinstructions that should not be brought to retirement. An
invalidation is necessary on a cycle if there exists a
microinstruction that will be committed on that cycle that satisfies
one of the following conditions: the microinstruction resulted in an
exception, the microinstruction is a jump, or the microinstruction is
a halt. Let $\funcfont{invalidate?} : \roblines{IC}^\ast$ be a predicate
over ROBs that holds iff the ROB indicates that an invalidation will
be required.

Let \trs{\mrbi{\MAICM}} be a transition system, where
$S_{\mrbi{\MAICM}} : S_{\MAICM} \times (\uinsts{IC} \times
\robids)^\ast$.

\[
  \inferrule[rob-issue-jmp]{Q = \abracket{u, \textit{rb}} \bullet Q^\prime \\ \funcfont{minst-op}(u) \in \{ \mathtt{mjg}, \mathtt{mjge} \} \\ \neg\halted}{\abracket{S, Q} \xtrans{\mrbi{\MAICM}}\\ \abracket{[\rob \mapsto \rob \mapp \sequence{\abracket{\textit{rb}, \funcfont{minst-op}(u), \texttt{nil}, \boolf, 0, \boolf}}]S, Q^\prime}}
\]

\noindent\texttt{mtsx-start}, \texttt{mtsx-end}, and \texttt{mhalt} also don't
write to a register, but they are marked as ready immediately upon issue.
\[
  \inferrule[rob-issue-halt-tsx-end]{Q = \abracket{u, \textit{rb}} \bullet Q^\prime \\ \funcfont{minst-op}(u) \in \{ \texttt{mtsx-end}, \texttt{mhalt} \} \\ \neg\halted}{\abracket{S, Q} \xtrans{\mrbi{\MAICM}}\\ \abracket{[\rob \mapsto \rob \mapp \sequence{\abracket{\textit{rb}, \funcfont{minst-op}(u), \texttt{nil}, \boolt, 0, \boolf}}]S, Q^\prime}}
\]

\[
  \inferrule[rob-issue-tsx-start]{Q = \abracket{u, \textit{rb}} \bullet Q^\prime \\ u = \instr{\texttt{mtsx-start}\ c} \\ \neg\halted}{\abracket{S, Q} \xtrans{\mrbi{\MAICM}}\\ \abracket{[\rob \mapsto \rob \mapp \sequence{\abracket{\textit{rb}, \funcfont{minst-op}(u), \texttt{nil}, \boolt, c, \boolf}}]S, Q^\prime}}
\]

\[
  \inferrule[rob-issue-other]{Q = \abracket{u, \textit{rb}} \bullet Q^\prime \\ \funcfont{minst-op}(u) \notin \{ \mathtt{mjg}, \mathtt{mjge}, \texttt{mtsx-start}, \texttt{mtsx-end}, \texttt{mhalt} \} \\ \neg\halted}{\abracket{S, Q} \xtrans{\mrbi{\MAICM}}\\ \abracket{[\rob \mapsto \rob \mapp \sequence{\abracket{\textit{rb}, \funcfont{minst-op}(u), \funcfont{reg-dst}(u), \boolf, 0, \boolf}}]S, Q^\prime}}
\]


Let \trs{\mrbw{\MAICM}} be a transition system, where
$S_{\mrbw{\MAICM}} : S_{\MAICM} \times \resstations{IC}^\ast$.

\textsc{rob-wrb-rdy} describes how the ROB is updated when a RS becomes
ready. Its definition hinges on two functions: $\funcfont{comp-val}$,
which uses the source operand values in the RS to compute the result
of the RS's microoperation, and $\funcfont{comp-exc}$ which
determines if the microoperation should result in an exception
instead. The appropriate ROB entry is updated with the result of these
two functions. In a MA state reachable from a clean start state, it
should always be the case that if a RS becomes ready, there exists
exactly one ROB line with that RS's destination ID in the ROB. 

\[
  \inferrule[rob-wrb-rdy]{Q = \textit{rs} \bullet Q^\prime \\ \cyclec = \rscpc_\textit{rs} \\ \rsbusy_\textit{rs} \\ \rsexec_\textit{rs} \\ \abracket{\exists i \from i \in \mathbb{N} \from \robid_{\rob(i)} = \rsdst_\textit{rs}} \\ \text{Let } i = \min_{j \in \mathbb{N} \wedge \robid_{\rob(j)} = \rsdst_\textit{rs}} j \\ \neg\halted}{\abracket{S, Q} \xtrans{\mrbw{\MAICM}} \La[\rob \mapsto [i \mapsto \\[\robval \mapsto \funcfont{comp-val}(rs, S), \robexcp \mapsto \funcfont{comp-exc}(\textit{rs})]\rob(i)]\rob]S\\, Q^\prime\Ra}
\]

\[
  \inferrule[rob-wrb-notrdy]{Q = \textit{rs} \bullet Q^\prime \\ \cyclec \neq \rscpc_\textit{rs} \vee \neg\rsbusy_\textit{rs} \vee \neg \rsexec_\textit{rs} \vee \neg \abracket{\exists i \from i \in \mathbb{N} \from \robid_{\rob(i)} = \rsdst_\textit{rs}} \\ \neg\halted}{\abracket{S, Q} \xtrans{\mrbw{\MAICM}} \abracket{S, Q^\prime}}
\]

%\drew{Note that we are assuming that if an RS is ready, its ROB destination ID corresponds to an entry that is in the ROB}


Let \trs{\mrbc{\MAICM}} be a transition system, where
$S_{\mrbc{\MAICM}} : S_{\MAICM} \times \roblines{IC}^\ast$.

\[
  \inferrule[rob-commit-invl]{Q = \textit{rl} \bullet Q^\prime \\ \robrdy_\textit{rl} \\ \robexcp_\textit{rl} \vee \robmop_\textit{rl} \in \{ \texttt{mhalt}, \texttt{mjg}, \texttt{mjge} \} \\ \neg\halted}
  {\abracket{S, Q} \xtrans{\mrbc{\MAICM}} \abracket{[\rob \mapsto \emptyseq]S, \emptyseq}}
\]

% \drew{The below could be modified to indicate that we're just popping one element off of the ROB in the state if it is unclear}
\[
  \inferrule[rob-commit-ok]{Q = \textit{rl} \bullet Q^\prime \\ \robrdy_\textit{rl} \\ \neg\robexcp_\textit{rl} \\ \robmop_\textit{rl} \notin \{ \texttt{mhalt}, \texttt{mjg}, \texttt{mjge} \} \\ \neg\halted}
  {\abracket{S, Q} \xtrans{\mrbc{\MAICM}} \abracket{[\rob \mapsto Q^\prime]S, Q^\prime}}
\]

\[
  \inferrule[rob-commit-notrdy]{Q = \textit{rl} \bullet Q^\prime \\ \neg\robrdy_\textit{rl} \\ \neg\halted}
  {\abracket{S, Q} \xtrans{\mrbc{\MAICM}} \abracket{S, \emptyseq}}
\]

Let \trs{\MAICM-\rob} be a transition system, where $S_{\MAICM-\rob} = S_{\MAICM} \times \natc$.

\[
  \inferrule[rob]{\abracket{S, \funcfont{decode-ic}(\funcfont{fetch-n}(\imem, \pc, n), \rob)} \xtrans{\mrbi{\MAICM}}^\ast \abracket{S^\prime, \emptyseq} \\ \abracket{S^\prime, \rsf} \xtrans{\mrbw{\MAICM}}^\ast \abracket{S^{\prime\prime}, \emptyseq} \\  \abracket{S^{\prime\prime}, \rob_{S^{\prime\prime}}} \xtrans{\mrbc{\MAICM}}^\ast \abracket{S^{\prime\prime\prime}, \emptyseq} \\ \neg\halted}
  {\abracket{S, n} \xtrans{\MAICM-\rob} \abracket{[\rob \mapsto \rob_{S^{\prime\prime\prime}}]S, n}}
\]


\paragraph{\rsf}

Let $\robids? = \robids \cup \{ \texttt{nil} \}$.

Let
$\funcfont{detect-raw-ic} : (\uinsts{IC} \times \robids)^\ast \rightarrow
(\robids? \times \robids?)^\ast$ be a function that given a sequence
of microinstructions each paired with the ROB entry they will be
assigned to, will determine for each microinstruction in the list that
uses a register whether that register is being written by a prior
microinstruction in the list. That is, if
$\funcfont{detect-raw-ic}(\sigma) = \pi$ and $\pi(i) = \abracket{a, b}$
then:
\[
  a = \begin{cases}
    \sigma(j)(2) &\parbox{6cm}{$\text{if } \funcfont{reg-op}_1(\sigma(i)(1))\downarrow \wedge \text{ for } S = \{ k \in \mathbb{N} \from k < i \wedge \funcfont{reg-dst}(\sigma(k)(1)) = \funcfont{reg-op}_1(\sigma(i)(1)) \}, \vert S \vert > 0 \wedge j = \max(S)$}\\
    \texttt{nil} &\text{otherwise}
  \end{cases}
\]
\[
  b = \begin{cases}
    \sigma(j)(2) &\parbox{6cm}{$\text{if } \funcfont{reg-op}_2(\sigma(i)(1))\downarrow \wedge  \text{ for } S = \{ k \in \mathbb{N} \from k < i \wedge \funcfont{reg-dst}(\sigma(k)(1)) = \funcfont{reg-op}_2(\sigma(i)(1)) \}, \vert S \vert > 0 \wedge j = \max(S)$}\\
    \texttt{nil} &\text{otherwise}
  \end{cases}
\]

Let
$\funcfont{next-idle-ic} : \resstations{IC}^\ast \rightharpoonup \mathbb{N}$
be a function that finds the index of an idle RS in the given sequence
of reservation stations.
\[
  \funcfont{next-idle-ic}(\sigma) = \begin{cases}
    \min(S) &\text{if } S = \{ i \in \fndom(\sigma) \from \neg\rsbusy_{\sigma(i)} \} \wedge \vert S \vert > 0\\
    \uparrow &\text{otherwise}
  \end{cases}
\]

Let
$\funcfont{rs-get-ic} : \rsids \times \resstations{IC}^\ast
\rightharpoonup \resstations{IC}$ be a function that finds the first RS
that has a particular ID in a sequence of RSes. That is,
\[
  \funcfont{rs-get-ic}(x, \sigma) = \begin{cases}
    \sigma(\min(S))&\text{if } \text{let } S = \{ j \in \mathbb{N} \from \rsid_{\sigma(j)} = x\}, \vert S \vert > 0\\
    \uparrow &\text{otherwise}
  \end{cases}
\]

Let \trs{\mrsfi{\MAICM}} be a transition system, where
$S_{\mrsfi{\MAICM}} : S_{\MAICM} \times (\uinsts{IC} \times
\robids \times \robids? \times \robids? \times \natc)^\ast$.

When issuing a microinstruction to a reservation station, \MAICM\ needs
to determine for each source operand of the microinstruction whether
that operand is going to come from another microinstruction, the
register file or a constant.
$\funcfont{setup-op-ic}_1 : \uinsts{IC} \times \robids? \times \resstations{IC} \times S_{\MAICM}
\rightarrow \resstations{IC}$ is a function that will perform this setup
for the first source operand, and $\funcfont{setup-op-ic}_2$ does the same
for the second source operand.

\begin{flalign*}
  &\funcfont{setup-op-ic}_1(u, \textit{dep}, \textit{rs}, S) =\\ &\begin{cases}
    [\rsqj \mapsto \texttt{nil}, \rsvj \mapsto 0]\textit{rs} &\text{if } \funcfont{minst-op}(u) = \texttt{mnoop}\\
    [\rsqj \mapsto \textit{dep}]\textit{rs} &\text{if } \textit{dep} \neq \texttt{nil}\\
    [\rsqj \mapsto \texttt{nil}, \rsvj \mapsto \robval_d]\textit{rs} &\text{if } \text{let } r_1 = \funcfont{reg-op}_1(u),\\&d = \funcfont{rob-get}(\regstreorder_{\regstat(r_1)}, \rob_S); \\&\regstat(r_1) \downarrow \wedge \regstbusy_{\regstat(r_1)} \wedge d \downarrow \wedge \robrdy_d\\
    [\rsqj \mapsto \regstreorder_{\regstat(r_1)}]\textit{rs} &\text{if } \text{let } r_1 = \funcfont{reg-op}_1(u),\\& d = \funcfont{rob-get}(\regstreorder_{\regstat(r_1)}, \rob_S); \\&\regstat(r_1) \downarrow \wedge \regstbusy_{\regstat(r_1)} \wedge (d \uparrow \vee \neg\robrdy_d)\\
    \parbox{3cm}{$[\rsqj \mapsto \texttt{nil}, \rsvj \mapsto \rf{\funcfont{reg-op}_1(u)}]\textit{rs}$} &\text{otherwise}
  \end{cases}
\end{flalign*}

\begin{flalign*}
  &\funcfont{setup-op-ic}_2(u, \textit{dep}, \textit{rs}, S) =\\ &\begin{cases}
    [\rsqk \mapsto \texttt{nil}, \rsvk \mapsto 0]\textit{rs} &\text{if } \funcfont{minst-op}(u) = \texttt{mnoop}\\
    [\rsqk \mapsto \textit{dep}]\textit{rs} &\text{if } \textit{dep} \neq \texttt{nil}\\
    [\rsqk \mapsto \texttt{nil}, \rsvk \mapsto \robval_d]\textit{rs} &\text{if } \text{let } r_2 = \funcfont{reg-op}_2(u),\\& d = \funcfont{rob-get}(\regstreorder_{\regstat(r_2)}, \rob_S); \\&\regstat(r_2) \downarrow \wedge \regstbusy_{\regstat(r_2)} \wedge d \downarrow \wedge \robrdy_d\\
    [\rsqk \mapsto \regstreorder_{\regstat(r_2)}]\textit{rs} &\text{if } \text{let } r_2 = \funcfont{reg-op}_2(u),\\& d = \funcfont{rob-get}(\regstreorder_{\regstat(r_2)}, \rob_S); \\&\regstat(r_2) \downarrow \wedge \regstbusy_{\regstat(r_2)} \wedge (d \uparrow \vee \neg\robrdy_d)\\
    \parbox{3cm}{$[\rsqk \mapsto \texttt{nil}, \rsvk \mapsto \rf{\funcfont{reg-op}_2(u)}]\textit{rs}$} &\text{otherwise}
  \end{cases}
\end{flalign*}

\[
  \inferrule[rsf-issue]{Q = \abracket{u, \textit{rb}, \textit{dep1}, \textit{dep2}, \textit{ipc}} \bullet Q^\prime \\ \funcfont{next-idle-ic}(\rsf)\downarrow \\ \funcfont{rs-needed?}(\funcfont{minst-op}(u)) \\
    \text{let } i = \funcfont{next-idle-ic}(\rsf) \\ \text{let } \textit{rs} = \funcfont{setup-op-ic}_2(u, \textit{dep2}, \funcfont{setup-op-ic}_1(u, \textit{dep1}, \rsf(i), S), S) \\ \neg\halted}
  {\abracket{S, Q} \xtrans{\mrsfi{\MAICM}} \La[\rsf \mapsto [i \mapsto [\rsmop \mapsto \funcfont{minst-op}(u),\\ \rsdst \mapsto \textit{rb}, \rsbusy \mapsto \boolt, \rspc \mapsto \textit{ipc}]\textit{rs}]\rsf]S, Q^\prime\Ra}
\]

\[
  \inferrule[rsf-issue-nors]{Q = \abracket{u, \textit{rb}, \textit{dep1}, \textit{dep2}, \textit{ipc}} \bullet Q^\prime \\ \neg\funcfont{rs-needed?}(\funcfont{minst-op}(u)) \\ \neg\halted}
  {\abracket{S, Q} \xtrans{\mrsfi{\MAICM}} \abracket{S, Q^\prime}}
\]

Let \trs{\mrsfe{\MAICM}} be a transition system, where
$S_{\mrsfe{\MAICM}} : S_{\MAICM} \times \resstations{IC}^\ast$.

Let $\funcfont{mop-time} : \uops{IC} \rightarrow \natc$ be a
function that determines how many cycles it takes to execute the given
microoperation.

Note that this transition system does not handle setting the \rsexec\
field to \boolf. $\mathcal{M}_{\MAICM-\rsf-\text{wr-b}}$ takes care of
this with the rule rsf-wb-ready.

Let
$\funcfont{check-barrier-start} : \robids \times \roblines{IC}^\ast
\rightarrow \bools$ be a predicate that determines whether it's OK for
the barrier microinstruction associated with the given ROB entry to
begin execution. This is true iff there are no uncommitted in-flight
memory access microinstructions prior to the barrier microinstruction
in question in program
order. $\funcfont{check-barrier-start}(\textit{id}, \textit{lines})$
can be computed by determining if any of the ROB lines returned by
$\funcfont{rob-before}(\textit{id}, \textit{lines})$ have
microoperations satisfying \funcfont{memory-op?}.

Let
$\funcfont{check-memory-start} : \robids \times \roblines{IC}^\ast
\rightarrow \bools$ be a predicate that determines whether it's OK for
the memory access microinstruction associated with the given ROB entry
to begin execution. This is true iff there are no uncommitted
in-flight memory barrier microinstructions prior to the barrier
microinstruction in question in program
order. $\funcfont{check-memory-start}(\textit{id}, \textit{lines})$
can be computed by determining if any of the ROB lines returned by
$\funcfont{rob-before}(\textit{id}, \textit{lines})$ have
microoperations satisfying \funcfont{barrier-op?}.

Note that here for simplicity we assume that \funcfont{barrier-op?}
and \funcfont{memory-op?} are mutually exclusive, \eg\ that no
microoperation exists that satisfies both predicates.

\[
