Let \trs{\mrsfw{\MAICM}} be a transition system, where
$S_{\mrsfw{\MAICM}} : S_{\MAICM} \times \resstations{IC}^\ast$.

$\funcfont{prop-single-ic} : \robids \times \natc \times
\resstations{IC} \rightarrow \resstations{IC}$ is a function that propagates a
completed RS execution (with the result being written to the ROB entry
with the given ID) to another RS.

\begin{flalign*}
  &\funcfont{prop-single-ic}(\textit{dst}, \textit{val}, \textit{rs}) =\\&\begin{cases}
    [\rsqj \mapsto \texttt{nil}, \rsvj \mapsto \textit{val}, \rsqk \mapsto \texttt{nil}, \rsvk \mapsto \textit{val}]\textit{rs} & \text{if } \rsqj = \textit{dst} \wedge \rsqk = \textit{dst}\\
    [\rsqj \mapsto \texttt{nil}, \rsvj \mapsto \textit{val}]\textit{rs} & \text{if } \rsqj = \textit{dst} \wedge \rsqk \neq \textit{dst}\\
    [\rsqk \mapsto \texttt{nil}, \rsvk \mapsto \textit{val}]\textit{rs} & \text{if } \rsqj \neq \textit{dst} \wedge \rsqk = \textit{dst}\\
    \textit{rs} & \text{otherwise}
  \end{cases}
\end{flalign*}

$\funcfont{prop-val-ic} : \robids \times \natc \times
\resstations{IC}^\ast \rightarrow \resstations{IC}^\ast$ applies
$\funcfont{prop-single-ic}$ with the given arguments to each element
of the given sequence of RSes to produce a new sequence of RSes.

\[
  \inferrule[rsf-wb-ready]{Q = \textit{rs} \bullet Q^\prime \\ \rsbusy_\textit{rs} \\ \rsexec_\textit{rs} \\ \cyclec = \rscpc_\textit{rs} \\
    \text{let } \textit{rsi} = \funcfont{rs-get-ic}(\rsid_\textit{rs}, \rsf) \\ \text{let } \textit{val} = \funcfont{comp-val}(\textit{rs}, S) \\ \text{let } \textit{excp} = \funcfont{comp-exc}(\textit{rs}, S) \\ \textit{rs-f}^\prime = \funcfont{prop-val-ic}(\rsdst_\textit{rs}, \textit{val}, \rsf) \\ \neg\halted}
  {\abracket{S, Q} \xtrans{\mrsfw{\MAICM}} \La[\rsf \mapsto [\textit{rsi} \mapsto\\ [\rsbusy \mapsto \boolf, \rsexec \mapsto \boolf]\textit{rs}]\textit{rs-f}^\prime]S, Q^\prime\Ra}
\]

\[
  \inferrule[rsf-wb-notready]{Q = \textit{rs} \bullet Q^\prime \\ \neg\rsbusy_\textit{rs} \vee \neg\rsexec_\textit{rs} \vee \cyclec \neq \rscpc_\textit{rs} \\ \neg\halted}
  {\abracket{S, Q} \xtrans{\mrsfw{\MAICM}} \abracket{S, Q^\prime}}
\]

Let \trs{\MAICM-\rsf} be a transition system, where
$S_{\MAICM-\rsf} = S_{\MAICM} \times \natc$.

Let
$\funcfont{decode-detect-raw-ic} : \insts{IC}^\ast \rightarrow (\uinsts{IC}
\times \robids \times \robids ? \times \robids ?))^\ast$
be a function that decodes the given sequence of instructions into a
sequence of microinstructions (using $\funcfont{decode-ic}$), then identifies
any read-after-write hazards for the (up to) two source operands for
each microinstruction (using $\funcfont{detect-raw-ic}$).

\begin{align*}
  &\text{Let } \pi = \funcfont{decode-detect-raw-ic}(\sigma).\\
  &\text{Let } \rho = \funcfont{decode-ic}(\sigma), \text{Let } \tau = \funcfont{detect-raw-ic}(\rho).\\
  &\text{Note that } \fndom(\rho) = \fndom(\tau).\\
  &\abracket{\forall i \from i \in \fndom(\rho) \from \pi(i) = \abracket{\rho(i)(1), \rho(i)(2), \tau(i)(1), \tau(i)(2)}}.
\end{align*}


\[
  \inferrule[rsf]{\abracket{S, \funcfont{decode-detect-raw-ic}(\funcfont{fetch-n}(\imem, \pc, n))} \xtrans{\mrsfi{\MAICM}}^\ast \abracket{S^\prime, \emptyseq} \\
    \abracket{S^\prime, \rsf_{S^\prime}} \xtrans{\mrsfe{\MAICM}}^\ast \abracket{S^{\prime\prime}, \emptyseq} \\
    \abracket{S^{\prime\prime}, \rsf_{S^{\prime\prime}}} \xtrans{\mrsfw{\MAICM}}^\ast \abracket{S^{\prime\prime\prime}, \emptyseq} \\ \neg\halted}
  {\abracket{S, n} \xtrans{\MAICM-\rsf} \abracket{[\rsf \mapsto \rsf_{S^{\prime\prime\prime}}]S, n}}
\]

\paragraph{\cmem}

$\funcfont{do-cache} : \powerset{\natc} \times (\natc
\rightharpoonup \natc) \times (\natc \rightharpoonup \natc)
\rightarrow (\natc \rightharpoonup \natc)$ is a function that takes in
a set of addresses to prefetch, a data memory and a cache and returns
the cache after caching all of the given addresses into it.

\[
  \trs{\mcc{\MAICM}}
\] is a transition system, where
$S_{\mcc{\MAICM}} = S_{\MAICM} \times \resstations{IC}^\ast$.

\[
  \inferrule[ma-cmem-commit-ldr]{Q = \textit{rs} \bullet Q^\prime \\ \cyclec = \rscpc_\textit{rs} \\ \rsbusy_\textit{rs} \\ \rsexec_\textit{rs} \\ \rsmop_\textit{rs} \in \{ \texttt{mldri}, \texttt{mldr} \} \\ a = \rsvj_\textit{rs} \plusc \rsvk_\textit{rs} \\ \neg\funcfont{comp-exc}(\textit{rs}) \\ \neg\halted \\ \cmem^\prime = [a \mapsto \partialget{\dmem}{a, 0}]\cmem}{\abracket{S, Q} \xtrans{\mcc{\MAICM}} \\\abracket{[\cmem \mapsto \funcfont{do-cache}(\prefetch(a), \dmem, \cmem^\prime)]S, Q^\prime}}
\]

\[
  \inferrule[ma-cmem-commit-other]{Q = \textit{rs} \bullet Q^\prime \\ \cyclec \neq \rscpc_\textit{rs} \vee \neg\rsbusy_\textit{rs} \vee \neg\rsexec_\textit{rs} \vee \rsmop_\textit{rs} \notin \{ \texttt{mldri}, \texttt{mldr} \} \\ \vee \funcfont{comp-exc}(\textit{rs}) \\ \neg\halted}{\abracket{S, Q} \xtrans{\mcc{\MAICM}} \abracket{[\cmem \mapsto S, Q^\prime}}
\]

