\subsection{Formal Semantics of \MAICHM}
\label{sec:maichm-semantics}
\subsubsection{Transition System}
\[
  \trs{\MAICHM}
\] is a deterministic transition system.  States of \M{\MAICHM} are
\M{\MAICM} states augmented with history information:
$S_\MAICHM = S_\MAICM \times H_\MAICM$.

\[
  H_\MAICM : \abracket{\mahcommitcyc, \mahstartcyc, \mahcommitcache, \mahcacheeffects, \mahlines}
\]

\begin{itemize}
  \item $\mahcommitcyc : \natc$ is the cycle during which the most recent commit occurred
  \item $\mahstartcyc : \natc$ is the first cycle for which this history state has data
  \item $\mahcommitcache : \natc \rightharpoonup \natc$ is the cache state, without any updates that may have occurred since the last instruction commit
  \item $\mahcacheeffects : \robids \rightharpoonup (\natc \rightharpoonup \natc)$ maps a ROB identifier to the cache entries that should be added to the cache after committing that ROB line's microinstruction
  \item $\mahlines : \mahstatuslines^\ast$ contains information about the progress of all in-flight microinstructions
\end{itemize}

$\mahstatuslines : \abracket{\mahslrob, \mahslpc, \mahsllines}$

\begin{itemize}
\item $\mahslrob : \robids$ is the ID of the ROB line that this status
  information is for
\item $\mahslpc : \natc$ is the PC corresponding to the instruction
  loaded into the ROB line with an ID equal to $\mahslrob$
\item $\mahsllines : \mahstatuses^\ast$ is the sequence of statuses
  corresponding to this ROB's progress
\end{itemize}

$\mahstatuses ::= \texttt{fetch}\ \textit{pc}\ \textit{rsi} \ \vert\ \texttt{exec}\ \vert\ \texttt{wr-b}\ \textit{cache}\ \vert\ \texttt{delay} \vert\ \texttt{post-comm}$

\begin{itemize}
\item $\texttt{fetch} \ \textit{pc}\ \textit{rsi}$\ where
  $\textit{pc} \in \natc$ and
  $\textit{rsi} \in \rsids \cup \{ \texttt{nil} \}$ indicates that the
  microinstruction was fetched and issued. If
  $\textit{rsi} \neq \texttt{nil}$ then it indicates the RS to which
  this instruction was issued. If $\textit{rsi} = \texttt{nil}$, the
  microinstruction does not require a RS. $\textit{pc}$ indicates the
  PC of the instruction corresponding to the microinstruction that was
  fetched and issued.
\item \texttt{exec} indicates that the microinstruction was executing
  in an RS.
\item $\texttt{wr-b}\ \textit{cache}$ where
  $\textit{cache} \in \natc \rightharpoonup \natc$ indicates that the
  instruction wrote back, and $\textit{cache}$ indicates the value of
  the cache at the time of the write back.
\item \texttt{delay} indicates that the microinstruction either had
  not started execution because it was waiting on a dependency, or it
  had completed execution and written back to the ROB, but the ROB
  line had not yet been committed as another in-flight instruction
  that comes earlier in program order had not yet been committed.
\item \texttt{post-comm} indicates that the microinstruction is a
  \texttt{mem-check} or \texttt{memi-check} microinstruction that has
  been committed before its corresponding \texttt{mldr} or
  \texttt{mldri} instruction. This is the only case where a
  microinstruction's status line is retained after it is retired.
\end{itemize}

%It is expected that entries in $\mahlines$ will not have duplicate
%$\mahslrob$ values.

The history information gathered by \MAICHM{} will be used to
determine whether an arbitrary \MAICHM{} state is ``\good'', where
``\good'' means essentially that when the state is invalidated back to
the point at which the earliest in-flight instruction was issued and
run forward, it is possible to reach that state. All invalidated
states are considered \good, so the only states that we need to worry
about here are those that have in-flight instructions (a nonempty
pipeline).

% \[
%   \inferrule[halted]{\halted}{\abracket{S, H} \xtrans{\MAICHM} \abracket{S, H}}
% \]

% \[
%   \inferrule[stepall]{\neg\halted \\ \text{Let } n = \funcfont{max-fetch-n}(S) \\
%     \abracket{S, n} \xtrans{\MAICM-\regstat} \abracket{\abracket{..., \regstat^\prime, ...}, n} \\
%     S \xtrans{\MAICM-\pc} \abracket{..., \pc^\prime, ...} \\
%     S \xtrans{\MAICM-\tsx} \abracket{..., \tsx^\prime, ...} \\
%     S \xtrans{\MAICM-\rfv} \abracket{..., \rfv^\prime, ...} \\
%     S \xtrans{\MAICM-\rob} \abracket{..., \rob^\prime, ...} \\
%     \abracket{S, n} \xtrans{\MAICM-\rsf} \abracket{\abracket{..., \rsf^\prime, ...}, n}\\
%     S \xtrans{\MAICM-\cmem} \abracket{..., \cmem^\prime, ...}\\
%     \abracket{S, H} \xtrans{\MAICHM-\textit{hist}} \abracket{S^\prime, H^\prime}
%   }{\abracket{S, H} \xtrans{\MAICHM} \La[\regstat \mapsto \regstat^\prime, \fetchpc \mapsto \fetchpc \plusc n, \pc \mapsto \pc^\prime,\\ \tsx \mapsto \tsx^\prime, \rfv \mapsto \rfv^\prime, \rob \mapsto \rob^\prime, \rsf \mapsto \rsf^\prime, \cmem \mapsto \cmem^\prime]S, H^\prime\Ra}
% \]

$\xtrans{\MAICHM}$ treats the first component of the state in the
same way that \MAICM\ does. That is:
\[
  \abracket{s, h} \xtrans{\MAICHM} \abracket{s^\prime, h^\prime}
  \implies s \xtrans{\MAICM} s^\prime
\]

Let $\funcfont{will-commit?-ic} : S_\MAICM \rightarrow \bools$ be a function
that returns \boolt\ iff \rob\ is nonempty and given $q$ is the first
ROB line, $\robrdy_q$. This indicates that at least one
microinstruction will be committed on the next cycle.

Let
$\funcfont{to-commit-ic} : \roblines{IC}^\ast \rightarrow \roblines{IC}^\ast$
be a function that returns the sequence of ROB lines that will be
committed in the next step.

$\funcfont{to-commit-ic}(\sigma) = \sequence{\sigma_k}_{k < \max(S)}$, where:
\begin{flalign*}
  S = \{&i \in \fndom(\sigma) \from\\
        &\abracket{\forall x \from x \in \fndom(\sigma) \wedge x < i-1 \from \robrdy_{\sigma(x)} \wedge \neg\robexcp_{\sigma(x)} \wedge\\
        &\quad\robmop_{\sigma(x)} \notin \{ \texttt{mhalt}, \texttt{mjge}, \texttt{mjg} \} } \wedge\\
        &(\neg\robrdy_{\sigma(i)} \vee \robexcp_{\sigma(i)} \vee \robmop_{\sigma(i)} \in \{ \texttt{mhalt}, \texttt{mjge}, \texttt{mjg} \} \vee\\
        &i = \max(\fndom(\sigma))) \}
\end{flalign*}

Let $\funcfont{will-invld?-ic} : \roblines{IC}^\ast \rightarrow \bools$ be a
function that returns \boolt\ iff a microinstruction will be committed
that will result in an invalidation. Note that it is defined to only
check the last element of $\funcfont{to-commit-ic}(\sigma)$, as the
definition of $\funcfont{to-commit-ic}$ is such that if the returned
sequence contains an invalidation, it will always be the final element
of the sequence.

\begin{flalign*}
  &\funcfont{will-invld?-ic}(\sigma) \iff\\
  &\pi \neq \emptyseq \wedge (\robexcp_{\pi(i)} \vee \robmop_{\pi(i)} \in \{ \texttt{mhalt}, \texttt{mjge}, \texttt{mjg} \})\\
  &\text{ where } \pi = \funcfont{to-commit-ic}(\sigma),  i = \max(\fndom(\pi))
\end{flalign*}


\[
  \inferrule[ic-h-halted]{\halted}{\abracket{S, H} \xtrans{\MAICHM} \abracket{S, H}}
\]

\[
  \inferrule[ic-h-stepall]{\neg\halted \\ S \xtrans{\MAICM} S^\prime \\
    \abracket{S, H} \xtrans{\MAICHM-\mahcommitcyc} \abracket{S, \abracket{..., \mahcommitcyc^\prime, ...}} \\
    \abracket{S, H} \xtrans{\mhccc{\MAICHM}} \abracket{S, \abracket{..., \mahcommitcache^\prime, ...}} \\
    \abracket{S, H} \xtrans{\MAICHM-\mahcacheeffects} \abracket{S, \abracket{..., \mahcacheeffects^\prime, ...}} \\
    \abracket{S, H} \xtrans{\mhl{\MAICHM}} \abracket{S, \abracket{..., \mahlines^\prime, ...}} \\
    \abracket{S, H} \xtrans{\MAICHM-\mahstartcyc} \abracket{S, \abracket{..., \mahstartcyc^\prime, ...}}
  }
  {S \xtrans{\MAICHM} \La S^\prime, [\mahcommitcyc \mapsto \mahcommitcyc^\prime, \\\mahcommitcache \mapsto \mahcommitcache^\prime, \mahcacheeffects \mapsto \mahcacheeffects^\prime,\\ \mahlines \mapsto \mahlines^\prime, \mahstartcyc \mapsto \mahstartcyc^\prime]H\Ra}
\]

Note that in the below transition systems, it's not necessary to
handle ROB entries corresponding to ready jumps, ready halts, or ready
entries where the exception flag is set since the history is going to
be invalidated in those cases anyways. So, the below rules are not
going to handle those cases.

\paragraph{\mahcommitcyc}
\[
  \trs{\MAICHM-\mahcommitcyc}
\] is a transition
system. $S_{\MAICHM-\mahcommitcyc} = S_\MAICHM$.

\[
  \inferrule[ccyc-will-commit]{\neg\halted \\ \funcfont{will-commit?-ic}(S)}
  {\abracket{S, H} \xtrans{\MAICHM-\mahcommitcyc} \abracket{S, [\mahcommitcyc \mapsto \cyclec]H}}
\]

\[
  \inferrule[ccyc-will-not-commit]{\halted \vee \neg\funcfont{will-commit?-ic}(S)}
  {\abracket{S, H} \xtrans{\MAICHM-\mahcommitcyc} \abracket{S, H}}
\]

\paragraph{\mahcommitcache}

\[
  \trs{\mhccc{\MAICHM}}
\] is a transition
system.
$S_{\mhccc{\MAICHM}} = S_\MAICHM \times \roblines{IC}^\ast$.

\[
  \inferrule[commit-cache-commit]{Q = \textit{rl} \bullet Q^\prime \\ \robrdy_\textit{rl} \\ \robmop_\textit{rl} \in \{ \texttt{mldri}, \texttt{mldr} \} \\ \neg\funcfont{will-invld?-ic}(\rob) \\ \neg\halted \\
    \text{let } \textit{eff} = \partialget{\mahcacheeffects}{\robid_\textit{rl}, \emptyset} }
  {\abracket{\abracket{S, H}, Q} \xtrans{\mhccc{\MAICHM}}\\ \abracket{\abracket{S, [\mahcommitcache \mapsto \mahcommitcache \cup \textit{eff}]H}, Q^\prime}}
\]

\[
  \inferrule[commit-cache-rdy]{Q = \textit{rl} \bullet Q^\prime \\ \robrdy_\textit{rl} \\ \robmop_\textit{rl} \notin \{ \texttt{mldri}, \texttt{mldr} \} \\ \neg\funcfont{will-invld?-ic}(\rob) \\ \neg\halted}
  {\abracket{\abracket{S, H}, Q} \xtrans{\mhccc{\MAICHM}} \abracket{\abracket{S, H}, Q^\prime}}
\]

\[
  \inferrule[commit-cache-notrdy]{Q = \textit{rl} \bullet Q^\prime \\ \neg\robrdy_\textit{rl} \\ \neg\funcfont{will-invld?-ic}(\rob) \\ \neg\halted}
  {\abracket{\abracket{S, H}, Q} \xtrans{\mhccc{\MAICHM}} \abracket{\abracket{S, H}, \emptyseq}}
\]

% \[
%   \inferrule[commit-cache-commit]{Q = \textit{rl} \bullet Q^\prime \\ \robrdy_\textit{rl} \\ \robmop_\textit{rl} \notin \{ \texttt{mhalt}, \texttt{mjge}, \texttt{mjg} \} \\ \neg\halted}{\abracket{\abracket{S, H}, Q} \xtrans{\mhccc{\MAICHM}} \abracket{\abracket{S, [\mahcacheeffects \mapsto [\robid_\textit{rl} \mapsto \uparrow]\mahcacheeffects]H}, Q^\prime}}
% \]

\paragraph{\mahcacheeffects}

\[
  \trs{\mhceffc{\MAICHM}}
\] is a transition
system.
