\end{flalign*}

$\funcfont{init-h}_{\MAICM}(s) = \abracket{\cyclec_s, \cyclec_s, \emptyset, \emptyset, \emptyset}$

\begin{flalign*}
  S^{\textit{init}}_{\MAICM} =  \{ s \in &S_\MAICM \from \fetchpc_s = \pc_s \wedge \rob_s = \emptyseq \wedge \regstat_s = \emptyseq \wedge\\
