\section{Related Work}
\subsection{Image-Text Sarcasm Detection}
Existing approaches \cite{cai-etal-2019-multi, pan-etal-2020-modeling, xu-etal-2020-reasoning, liu-etal-2022-towards-multi-modal, tian-etal-2023-dynamic} used early or late fusion of the image and text modalities to capture the inter and intra-modal relationship for sarcasm. Recent methods \cite{Liang2021MultiModalSD, Liang2022MultiModalSD, Du2021GLMGL} employed Graph Neural Networks for image-text matching to learn cross-modal relationships. \citet{qin-etal-2023-mmsd2} employed CLIP encoder to extract image-text representations. These representations are fused using a cross-modal interaction mechanism. \citet{Tang2024LeveragingGL} exploited in-context learning ability of LLaVa by providing demonstration examples for training.

Our model AdS significantly differs from these approaches as it utilizes the pre-trained knowledge of CLIP by preventing updates to the original CLIP weights. Instead we use adapter-learning to learn sarcasm specific cues and then employ a modality interaction module to capture the distinct types of saracsm. 
\subsection{Adapter Learning}
\cite{Houlsby2019ParameterEfficientTL, Bapna2019SimpleSA, Pfeiffer2020AdapterFusionNT} introduced adapters in different positions of transformer layers for transfer learning in NLP. The idea was - adapters require a relatively small number of parameters for training and hence can effectively deal with catastrophic forgetting of LLMs for downstream tasks.
In the domain of multimodal learning, Clip-Adapter \cite{Gao2021CLIPAdapterBV} and AdaptFormer \cite{Chen2022AdaptFormerAV} fused features from adapters and CLIP encoders using a residual connection for optimization. The VL adapter \cite{Sung2021VLADAPTERPT} exploited the sharing of adapters between multiple tasks in vision-language setup. Very recently Tip-Adapter \cite{Zhang2022TipAdapterTA} used an adapter layer which would act as a memory unit for image classification tasks.

However, these methods introduce adapter layers in only one encoder branch (either visual or text), limiting cross-modal interaction learning. In contrast, we incorporate adapters in both branches and introduce adapter-state sharing, allowing the textual adapter to guide the visual adapter for enhanced sarcasm understanding.

\section{Preliminaries}
\textbf{CLIP Vision Encoder:} Image $I$ is divided into $m$ equal-sized patches. Each patch is projected into $d_{v}$ dimensional embedding space with positional embeddings to get the patch embedding $E^{0} (E^{0} \in \mathbb{R}^{m \times d_{v}} )$ for first transformer layer $V^{1}$. The patch embeddings $E^{i}$ are prepended with a learnable class embedding token $z_{i}$ and passed through L transformer blocks sequentially as follows:
\begin{equation}
[z^{i}, E^{i}] = \text{V}^{i}([z^{i-1}, E^{i-1}])
\quad i = 1, \dots, L
\end{equation}
The final image embedding $H^{V}$ is obtained by projecting $z^{L}$ into a shared embedding space as follows:
\begin{equation}
H^{V} = \text{Proj}_{I}(z^{L})
\quad H^{V} \in \mathbb{R}^{d}
\end{equation}
\textbf{CLIP Text Encoder:} Given an input text sequence $l$, it is tokenized into n tokens and are converted to $d_{t}$ dimensional word embeddings $W^{0} (W^{0} \in \mathbb{R}^{n \times d_{t}})$ with positional embeddings added.
Subsequently, they are processed sequentially through L transformer blocks as follows:
\begin{equation}
[W^{i}] = \text{T}^{i}([W^{i-1}])
\quad i = 1, \dots, L
\end{equation}
The final text embedding $H^{T}$ is obtained by projecting the embedding corresponding to the last token of the output from the last transformer layer into a shared embedding space as:
\begin{equation}
H^{T} = \text{Proj}_{T}(W^{L}[-1])
\quad H^{T} \in \mathbb{R}^{d}
\end{equation}

\section{Proposed Method}


\subsection{Problem Formulation}
Given a sample $x_{j} = (T_{j}, I_{j})$ where $T$ is the text and $I$ is the image, the goal is to assign $x_{j}$ with label ${y_{j}}$ from the label set $Y = \{sarcastic, nonsarcastic \}$.

\subsection{Adapter-state Sharing}
Figure \ref{fig:model} depicts the architecture of our proposed AdS (\textbf{Ad}apter-state \textbf{S}haring), a pluggable module for CLIP. To leverage the multimodal prior knowledge of CLIP, we incorporate adapter layers within both the textual and visual transformer blocks. Adapter $A$ is realized as:
\begin{equation}
 A(h) = W^{up}(\phi(W^{down}h))   
\end{equation}
where $W^{up}$ and $W^{down}$ are upsample and downsample projection layers respectively and $\phi$ is ReLU non-linearity.
Higher layers of CLIP learn more complex and discriminative features. Since sarcasm is a complex and nuanced phenomenon, we insert adapters into the upper transformer layers, ensuring that the model captures nuanced sarcasm cues while retaining CLIP’s strong foundational knowledge.
The text encoder can now be re-formulated with adapter layers added from $K^{th}$ transformer layer as:
\begin{equation}
\begin{split}
[W^{i}] & = \text{T}^{i}([W^{i-1}]) \quad i = 1, \dots, K-1 \\
[W^{i}] & = \text{T}^{i}([W^{i-1}]) + \alpha A_{T}^{i}([W^{i-1}])
\quad i = K, \dots, L
\end{split}
\end{equation}
where $ A_{T}^{i}$ is the adapter layer in the $i^{th}$ transformer block of the text encoder and $\alpha$ determines the retention factor of the adapter's information. 

Sarcasm relies heavily on nuanced image-text relationship. To effectively foster cross-modal information sharing, we introduce a novel adapter-state sharing mechanism, where the textual adapter states guide the visual adapter states to learn sarcastic cues from the image. To achieve this, we maintain a queue of textual adapter states $Q = \{ S_{j}^{T} \}_{j=K}^{L}$, where $S_{j}^{T} = A_{T}^{j}([W^{j-1}]) $  is the adapter output state from text transformer block $j$. For each visual adapter output, $S_{j}^{V} =  A_{V}^{j}([z^{j-1}, E^{j-1}])$, we compute its relative attention  weights corresponding to all textual adapter states using the following equations:
\begin{equation}
      Att = softmax(QWS_{j}^{V})
\end{equation}

where $Q \in \mathbb{R}^{(L-K+1) \times d^{\prime}}$, $\quad W \in  \mathbb{R}^{d^{\prime} \times d},
\quad S_{j}^{V} \in  \mathbb{R}^{d \times 1}$
% \[
% \text{where }Q \in \mathbb{R}^{(L-K+1) \times d^{\prime}}, 
% \quad W \in  \mathbb{R}^{d^{\prime} \times d},
% \quad S_{j}^{V} \in  \mathbb{R}^{d \times 1}, 
% \]

$Att \in \mathbb{R}^{(L-K+1) \times 1}$






% \begin{equation}
% \hat{Q} = QW
% \end{equation}
% \[
% \text{where } Q \in \mathbb{R}^{(L-K+1) \times d^{\prime}}, 
% \quad W \in  \mathbb{R}^{d^{\prime} \times d}, 
% \quad \hat{Q} \in \mathbb{R}^{(L-K+1) \times d}
% \]


$Att$ gives us the relative attention weights of each visual adapter state $S_{j}^{V}$ with all textual adapter states. To derive the final contribution $f^{j}$ of all textual adapter states, we perform a weighted summation using the computed attention scores.
\begin{equation}
   f^{j} = \sum\limits_{i=1}^{L-K+1}Att_{i} \cdot Q_{i}
   \quad f^{j} \in \mathbb{R}^{d}
\end{equation}
We now introduce adapters in the visual encoder from the $K^{th}$ transformer layer as:

\begin{equation}
\begin{split}
[z^{j}, E^{j}] &= \text{V}^{j}([z^{j-1}, E^{j-1}])
\quad j = 1, \dots, K-1 \\
[z^{j}, E^{j}] &= \text{V}^{j}([z^{j-1}, E^{j-1}]) + \alpha A_{V}^{j}([z^{j-1}, E^{j-1}]) + \gamma f^{j}
\end{split}
\end{equation}
\[
\quad j = K, \dots, L
\]
where $ A_{V}^{j}$ is the adapter layer in the $j^{th}$ transformer block of the visual encoder, $\alpha$ determines the retention factor of the adapter's information, $f^{j}$ is the weighted text  adapter shared information for $j^{th}$ visual adapter and $\gamma$ determines the retention factor for $f^{j}$. 



