\begin{example} \label{ex:example}
To demonstrate the proposed approach and compare it with traditional stratified samping, we consider a linear model for which the NeurAM can be computed analytically. 
%
Let $\Q(x) = x_1 + x_2$ and $\mu = \mathcal U([-1,1]^2)$. Then, a global minimizer of~\eqref{eq:loss_function} is given by
\begin{equation}
\E(x) = x_1 + x_2, \qquad \D(z) = \begin{bmatrix} \frac{z}2 & \frac{z}2 \end{bmatrix}^\top, \qquad \S(z) = z,
\end{equation}
with NeurAM given by $\{ x \in [-1,1]^2 \colon x_2 = x_1 \}$. Moreover, the latent variables follow a triangular distribution, $\E(X) \sim \mathcal T(-2,0,2)$, with CDF~\eqref{eq:CDF} given by
\begin{equation}
\F(t) = \begin{cases}
0, & \text{ if } t \le -2, \\
\frac18 t^2 + \frac12 t + \frac12, & \text{ if } -2 \le t \le 0, \\
- \frac18 t^2 + \frac12 t + \frac12, & \text{ if } 0 \le t \le 2, \\
1, & \text{ if } t \ge 2.
\end{cases}
\end{equation}
We then choose a number $S = 4$ of strata, and consider a uniform partition of the unit interval
\begin{equation}
A_1 = \left[ 0, \frac14 \right], \qquad A_2 = \left[ \frac14, \frac12 \right], \qquad A_3 = \left[ \frac12, \frac34 \right], \qquad A_4 = \left[ \frac34, 1 \right].
\end{equation}
From equation~\eqref{eq:Ds_def}, the NeurAM-based stratification of $[-1,1]^2$ is given by
\begin{equation}
\begin{aligned}
D_1 &= \left\{ x \in [-1,1]^2 \colon -1 < x_1 < \sqrt2-1, \quad -1 < x_2 < -x_1 + \sqrt2-2 \right\}, \\
D_2 &= \left\{ x \in [-1,1]^2 \colon -1 < x_1 < 1, \quad -x_1 + \sqrt2 - 2 < x_2 < -x_1 \right\}, \\
D_3 &= \left\{ x \in [-1,1]^2 \colon -1 < x_1 < 1, \quad -x_1 < x_2 < -x_1 + 2 - \sqrt2 \right\}, \\
D_4 &= \left\{ x \in [-1,1]^2 \colon 1-\sqrt2 < x_1 < 1, \quad -x_1 + 2 - \sqrt2 < x_2 < 1 \right\},
\end{aligned}
\end{equation}
which is shown in the left plot in \cref{fig:example}. 
%
We then have $\lambda(A_s) = 1/4$ for all $s = 1, \dots, 4$, and the local variances (we omit their derivation for brevity) are
\begin{equation}
\begin{aligned}
\Var^\mu[\Q(X) | X \in D_1] = \Var^\mu[\Q(X) | X \in D_4] &= \frac19, \\
\Var^\mu[\Q(X) | X \in D_2] = \Var^\mu[\Q(X) | X \in D_3] &= \frac{32}9 \sqrt2 - 5.
\end{aligned}
\end{equation}
Using~\eqref{eq:optimal_variances}, we have
\begin{equation}
\Var[\widehat q_\sMC^{(1)}] = \frac{16\sqrt2 - 22 + \sqrt{32\sqrt2 - 45}}{18N} \qquad \text{and} \qquad \Var[\widehat q_\sMC^{(2)}] = \frac{16\sqrt2 - 22}{9N},
\end{equation}
where $N$ is the computational budget. Let us now compare these results with the variance of a stratified Monte Carlo estimator, where the stratification is given by a regular grid with two subdivisions in each dimension and therefore $S=4$ strata in total
\begin{equation}
\widetilde D_1 = [-1, 0] \times [0, 1], \quad \widetilde D_2 = [0, 1] \times [0, 1], \quad \widetilde D_3 = [-1, 0] \times [-1, 0], \quad \widetilde D_4 = [0, 1] \times [-1, 0],
\end{equation}
which is shown in the right plot in \cref{fig:example}. 
%
In this case, for all $s = 1, \dots, 4$ we have
\begin{equation}
\Var^\mu[\Q(X) | X \in \widetilde D_i] = \frac16, 
\end{equation}
which implies
\begin{equation}
\Var[\widehat q_\sMC^{(1)}] = \frac1{6N} \qquad \text{and} \qquad \Var[\widehat q_\sMC^{(2)}] = \frac1{6N}.
\end{equation}
%
Moreover, notice that the variance of standard Monte Carlo is $\Var[\widehat q_\MC] = 2/(3N)$. 
%
Therefore, independently of the allocation strategy, the variance of the NeurAM-based stratified estimator ($\sim0.06/N$ and $\sim0.07/N$) is significantly smaller than the one given by a regular grid ($\sim0.17/N$), which already improves over the standard Monte Carlo estimator variance ($\sim0.67/N$).
\end{example}

\subsection{A heuristic algorithm to improve the stratification} \label{sec:heuristic}

In this section we focus on determining an \emph{optimal} stratification leading to estimators with minimal variance. 
%
Considering the two allocation strategies discussed in the previous section, and due to the bound \eqref{eq:bound_variances}, this amounts to solving the minimization problems
\begin{equation} \label{eq:optimization_strata_M}
\begin{aligned}
(\mathrm M1) \quad& \min_{0 = a_0 < a_1 < \cdots < a_{S-1} < a_S = 1} \sum_{s=1}^S \lambda(A_s) \sqrt{\Var^\mu[\Q(X) | X \in D_s]}, \\
(\mathrm M2) \quad& \min_{0 = a_0 < a_1 < \cdots < a_{S-1} < a_S = 1} \sum_{s=1}^S \lambda(A_s) \Var^\mu[\Q(X) | X \in D_s]. \\
\end{aligned}
\end{equation}
However, (M1) and (M2) might be challenging and computationally expensive to solve, so that it might be more effective to simply use a uniform stratification as discussed in \cref{ex:uniform}. 
%
In addition, we would need to solve nonlinear optimization problems in high dimensions, where the variances in the objective functions are not even known explicitly, but must be approximated. 
%
Therefore, we propose a heuristic strategy that iteratively refines the strata, while keeping the computational cost limited. 

We proceed as follows. Let $\mathcal A^{(1)}, \Lambda^{(1)}, \Sigma^{(1)}$ be defined as
\begin{equation}
\begin{aligned}
\mathcal A^{(1)} &= \{ a_0^{(1)}, a_1^{(1)} \} = \{ 0, 1 \}, \\
\Lambda^{(1)} &= \{ \lambda_1^{(1)} \}, \quad \lambda_1^{(1)} = a_1^{(1)} - a_0^{(1)} = 1, \\
\Sigma^{(1)} &= \{ \sigma_1^{(1)} \}, \quad \sigma_1^{(1)} = \Var^\mu \left[ \Q(X) | \F(\E(X)) \in [a_0^{(1)}, a_1^{(1)}] \right] = \Var^\mu[\Q(X)].
\end{aligned}
\end{equation}
Then, at each iteration we bisect the interval that contributes the most to the overall variance.
%
In particular, for all $j = 2, \dots, S$, select the index $i^*$ such that
\begin{equation}
i^* = 
\begin{cases}
\argmax_{i \in \{ 1, \dots, j-1 \}} \lambda_i^{(j-1)} \sqrt{\sigma_i^{(j-1)}}, & \text{ for allocation (1)}, \\ 
\argmax_{i \in \{ 1, \dots, j-1 \}} \lambda_i^{(j-1)} \sigma_i^{(j-1)}, & \text{ for allocation (2)}, \\ 
\end{cases}
\end{equation}
and pick a point $a^* \in [a_{i^*-1}^{(j-1)}, a_{i^*}^{(j-1)}]$. Then, define $\mathcal A^{(j)}, \Lambda^{(j)}, \Sigma^{(j)}$ as
\begin{equation}
\begin{aligned}
\mathcal A^{(j)} &= \{ a_i^{(j)} \}_{i=0}^j = \mathcal A^{(j-1)} \cup \{ a^* \}, \\
\Lambda^{(j)} &= \{ \lambda_i^{(j)} \}_{i=0}^j, \quad \lambda_i^{(j)} = a_i^{(j)} - a_{i-1}^{(j)}, \\
\Sigma^{(j)} &= \{ \sigma_i^{(j)} \}_{i=0}^j, \quad \sigma_i^{(j)} = \Var^\mu \left[ \Q(X) | \F(\E(X)) \in [a_{i-1}^{(j)}, a_i^{(j)}] \right].
\end{aligned}
\end{equation}
%
The resulting stratification is given by the points in $\mathcal A^{(S)}$ after the last iteration $j = S$. 
%
Finally, we need to specify how to select $a^*$ at each step. 
%
We emphasize that, due to the law of total variance, any point $a^*$ can be chosen, meaning that this procedure does not increase the variance of the resulting estimator independently of the selected point $a^*$. 
%
Nevertheless, we list here two alternatives that can be used in practice:
\begin{itemize}[leftmargin=*]
\item interval mid-point, i.e., $a^*_{\mathrm h} = (a_{i^*-1}^{(j-1)} + a_{i^*}^{(j-1)})/2$;
\item optimal value given by
\begin{equation}
a^*_{\mathrm o} = 
\begin{cases}
\begin{aligned}
\argmin_{a^* \in [a_{i^*-1}^{(j-1)}, a_{i^*}^{(j-1)}]} &\left\{ (a^* - a_{i^*-1}^{(j-1)}) \sqrt{\Var^\mu \left[ \Q(X) | \F(\E(X)) \in [a_{i^*-1}^{(j-1)}, a^*] \right]} \right. \\
&\left. + (a_{i^*}^{(j-1)} - a^*) \sqrt{\Var^\mu \left[ \Q(X) | \F(\E(X)) \in [a^*, a_{i^*}^{(j-1)}] \right]} \right\},
\end{aligned}
& \text{ for (1)}, \\
\begin{aligned}
\argmin_{a^* \in [a_{i^*-1}^{(j-1)}, a_{i^*}^{(j-1)}]} &\left\{ (a^* - a_{i^*-1}^{(j-1)}) \Var^\mu \left[ \Q(X) | \F(\E(X)) \in [a_{i^*-1}^{(j-1)}, a^*] \right] \right. \\
&\left. + (a_{i^*}^{(j-1)} - a^*) \Var^\mu \left[ \Q(X) | \F(\E(X)) \in [a^*, a_{i^*}^{(j-1)}] \right] \right\},
\end{aligned}
& \text{ for (2)}. 
\end{cases}
\end{equation}
\end{itemize}
%
Note that, in the latter case, the minimum is well-defined since the function to be minimized is continuous on a compact interval. 
%
Moreover, this choice provides the best variance reduction at each step, but it requires additional computations (one needs to solve a minimization problem), even if the surrogate model $\Q_{\mathrm S}$ can be use to estimate the variance of the strata.
%
Also, the optimization problem is, in this case, only one-dimensional, unlike (M1) and (M2) in \eqref{eq:optimization_strata_M}.

\section{Application to multifidelity estimators} \label{sec:multifidelity} 

The NeurAM-based stratification presented here can be integrated with other variance reduction methods to achieve even greater precision in the resulting estimates.
%
For example, it can be combined with multifidelity Monte Carlo estimators, as explained next. 
%
Let $\Q^\HF = \Q$ and assume that a cheap low-fidelity approximation $\Q^\LF$ of the high-fidelity model $\Q^\HF$ is also known. 
%
Let $w = \mathcal C^\HF / \mathcal C^\LF$ be the cost ratio between the two model fidelities. 
%
The available computational budget $N$, expressed in terms of high-fidelity model evaluations, can then be assembled from the high- and low-fidelity model evaluations $N^\HF$ and $N^\LF$, respectively, as
\begin{equation}
N = N^\HF + w N^\LF.
\end{equation}
It is possible to determine $N^\HF$ and $N^\LF$ so the resulting multifidelity estimator has minimum variance, or, in other words, an \emph{optimal allocation} can be computed in closed-form as~\cite{PWG16}
\begin{equation} \label{eq:optimal_allocation}
N^\HF = \frac{N}{1 + w \beta} \quad \text{and} \quad N^\LF = \beta N^\HF = \frac{\beta N}{1 + w \beta}, \quad \text{with} \quad \beta = \sqrt{\frac{\rho^2}{w(1 - \rho^2)}},
\end{equation}
where $\rho$ is the Pearson correlation coefficient between the two fidelities
\begin{equation} \label{eq:correlation}
\rho = \frac{\Cov^\mu \left[ \Q^\HF(X), \Q^\LF(X) \right]}{\sqrt{\Var^\mu[\Q^\HF(X)] \Var^\mu \left [\Q^\LF(X) \right]}}.
\end{equation}
The multifidelity Monte Carlo estimator is then defined as
\begin{equation} \label{eq:MFMC}
\widehat q_\MFMC = \frac1{N^\HF} \sum_{n=1}^{N^\HF} \Q^\HF(x_n) - \alpha \left( \frac1{N^\HF} \sum_{n=1}^{N^\HF} \Q^\LF(x_n) - \frac1{N^\LF} \sum_{n=1}^{N^\LF} \Q^\LF(x_n) \right),
\end{equation}
where the optimal value for the coefficient $\alpha$ is
\begin{equation} \label{eq:optimal_coefficient}
\alpha = \frac{\Cov^\mu \left[ \Q^\HF(X), \Q^\LF(X) \right]}{\Var^\mu \left[ \Q^\LF(X) \right]},
\end{equation}
and the samples $\{ x_n \}_{n=1}^{N^\LF}$ with $N^\LF > N^\HF$ are drawn from the distribution $\mu$. 
%
We remark that the estimator $\widehat q_\MFMC$ is unbiased, i.e., $\Ex[\widehat q_\MFMC] = q$, and has variance
\begin{equation} \label{eq:variance_MFMC}
\Var \left[ \widehat q_\MFMC \right] = \frac1N \Var^\mu \left[ \Q^\HF(X) \right] \left( \sqrt{1 - \rho^2} + \sqrt{w\rho^2} \right)^2 = \Var \left[ \widehat q_\MC \right] \left( \sqrt{1 - \rho^2} + \sqrt{w\rho^2} \right)^2.
\end{equation}
This implies that $\Var \left[ \widehat q_\MFMC \right] < \Var \left[ \widehat q_\MC \right]$, leading to variance reduction under the condition $\rho^2 > 4w/(1 + w)^2$. 

A multifidelity approach can be combined with stratified sampling by replacing the Monte Carlo estimator with the multifidelity Monte Carlo estimator in each stratum. In particular, for a NeurAM based stratification $\{ (A_s,D_s) \}_{s=1}^S$ and a collection of samples $\{ \{ x_n^{(s)} \}_{n=1}^{N^\LF_s} \}_{s=1}^S$ with $x_n^{(s)} \sim \mu |_{D_s}$, we have
\begin{equation} \label{eq:estimator_sMFMC_def}
\begin{aligned}
\widehat q_\sMFMC &= \sum_{s=1}^S \lambda(A_s) \left[ \frac1{N^\HF_s} \sum_{n=1}^{N^\HF_s} \Q^\HF(x_n^{(s)}) \right. \\
&\hspace{2.5cm} \left. - \alpha_s \left( \frac1{N^\HF_s} \sum_{n=1}^{N^\HF_s} \Q^\LF(x_n^{(s)}) - \frac1{N^\LF_s} \sum_{n=1}^{N^\LF_s} \Q^\LF(x_n^{(s)}) \right) \right],
\end{aligned}
\end{equation}
where, given the available computational budget in each stratum $\{ N_s \}_{s=1}^S$ such that $N = \sum_{s=1}^S N_s$ and still following \cite{PWG16}, an optimal allocation is given by
\begin{equation}
N^\HF_s = \frac{N_s}{1 + w \beta_s} \quad \text{and} \quad N^\LF = \beta_s N^\HF_s = \frac{\beta_s N_s}{1 + w \beta_s}, \quad \text{with} \quad \beta_s = \sqrt{\frac{\rho_s^2}{w(1 - \rho_s^2)}},
\end{equation}
where $\rho_s$ is the Pearson correlation coefficient in each stratum
\begin{equation}
\rho_s = \frac{\Cov^\mu \left[ \Q^\HF(X), \Q^\LF(X) | X \in D_s \right]}{\sqrt{\Var^\mu[\Q^\HF(X) | X \in D_s] \Var^\mu [\Q^\LF(X)| X \in D_s]}}.
\end{equation}
Moreover, the optimal values for the coefficients $\{ \alpha_s \}_{s=1}^S$ are
\begin{equation}
\alpha_s = \frac{\Cov^\mu \left[ \Q^\HF(X), \Q^\LF(X) | X \in D_s \right]}{\Var^\mu \left[ \Q^\LF(X) | X \in D_s \right]}.
\end{equation}
We notice that the stratified multifidelity Monte Carlo estimator remains unbiased, i.e., it holds $\Ex[\widehat q_\sMFMC] = q$, and, due to equations \eqref{eq:sMC_general_NeurAM} and \eqref{eq:variance_MFMC}, its variance is
\begin{equation} \label{eq:variance_sMFMCM}
\Var[\widehat q_\sMFMC] = \sum_{s=1}^S \frac{\lambda(A_s)^2}{N_s} \Var^\mu[\Q^\HF(X) | X \in D_s] \left( \sqrt{1 - \rho_s^2} + \sqrt{w\rho_s^2} \right)^2,
\end{equation}
which is dependent on the local correlations $\{ \rho_s \}_{s=1}^S$ in each stratum. In the next section we study how the variance can be optimized and provide conditions under which this approach is more effective than standard multifidelity Monte Carlo.

\begin{remark}
NeurAM is applicable to both low- and high-fidelity models to establish a shared space~\cite{ZGS24c}. This space can be used to reparameterize the low-fidelity model, thereby enhancing the correlation $\rho$ between the fidelities. For the remainder of this discussion, we assume that $\Q^\LF$ has already undergone reparameterization and demonstrates a strong correlation with $\Q^\HF$, satisfying the condition $\rho^2 > 4w/(1 + w)^2$. 
%
Although this reparameterization would provide an additional reduction in variance, it is not needed for the discussion that follows.
\end{remark}

% =============================================================
\subsection{Allocation strategies and analysis of the variance}
% =============================================================

Similar to the discussion in \cref{sec:variance_sMC}, we analyze two allocation strategies for the stratified multifidelity Monte Carlo estimator. 
%
An allocation that yields estimators with minimum variance involves selecting $N_s$ samples in stratum $s$ according to
\begin{equation} \label{eq:allocation1_MF}
N_s^{(1)} = \frac{\lambda(A_s)\sqrt{\Var^\mu[\Q(X) | X \in D_s]} \left( \sqrt{1 - \rho_s^2} + \sqrt{w\rho_s^2} \right)}{\sum_{r=1}^S \lambda(A_r)\sqrt{\Var^\mu[\Q(X) | X \in D_r]} \left( \sqrt{1 - \rho_r^2} + \sqrt{w\rho_r^2} \right)} N,
\end{equation}
while a proportional allocation  is still
\begin{equation} \label{eq:allocation2_MF}
N_s^{(2)} = \lambda(A_s)\,N.
\end{equation}
Replacing the two allocation strategies in equation \eqref{eq:variance_sMFMCM} gives
\begin{equation}
\begin{aligned}
\Var[\widehat q_\sMFMC^{(1)}] &= \frac1N \left\{ \sum_{s=1}^S \lambda(A_s) \sqrt{\Var^\mu[\Q(X) | X \in D_s]} \left( \sqrt{1 - \rho_s^2} + \sqrt{w\rho_s^2} \right) \right\}^2, \\
\Var[\widehat q_\sMFMC^{(2)}] &= \frac1N \sum_{s=1}^S \lambda(A_s) \Var^\mu[\Q(X) | X \in D_s] \left( \sqrt{1 - \rho_s^2} + \sqrt{w\rho_s^2} \right)^2,
\end{aligned}
\end{equation}
and, from Jensen's inequality, it is also easy to see that
\begin{equation}
\Var[\widehat q_\sMFMC^{(1)}] \le \Var[\widehat q_\sMFMC^{(2)}].
\end{equation}
It is evident and straightforward to verify that, if all the local correlations satisfy the condition that ensures variance reduction, i.e., $\rho_s^2 > 4w/(1+w)^2$ for all $s = 1, \dots, S$, then
\begin{equation}
\Var[\widehat q_\sMFMC^{(1)}] \le \Var[\widehat q_\sMC^{(1)}] \quad \text{and} \quad 
\Var[\widehat q_\sMFMC^{(2)}] \le \Var[\widehat q_\sMC^{(2)}].
\end{equation}
%
Moreover, the following result provides conditions under which stratification leads to multifidelity Monte Carlo estimator with reduced variance.

\begin{proposition} \label{pro:variance_MF}
Let $\widehat q_\sMFMC^{(1)}$ and $\widehat q_\sMFMC^{(2)}$ be the estimators defined in equation \eqref{eq:estimator_sMFMC_def} with computational budget $N$ and allocations given by \eqref{eq:allocation1_MF} and \eqref{eq:allocation2_MF}, respectively, and let $\rho$ and $\{ \rho_s \}_{s=1}^S$ be the overall and intra-stratum correlations between the high- and low-fidelity model. 
%
Assuming $\rho^2 \ge 4w/(1+w)^2$, the following two statements hold
\begin{enumerate}[leftmargin=*]
\item if $\bar\rho \ge \rho$, where $\bar\rho = \sum_{s=1}^S \lambda(A_s)\,\rho_s$, then $\Var[\widehat q_\sMFMC^{(1)}] \le \Var[\widehat q_\MFMC]$.
\item if $\rho_s \ge \rho$ for all $s = 1, \dots, S$, then $\Var[\widehat q_\sMFMC^{(2)}] \le \Var[\widehat q_\MFMC]$,
\end{enumerate}
\end{proposition}
\begin{proof}
First, statement $(ii)$ follows from the law of total variance and the fact that the function $f(x) = (\sqrt{1 - x^2} + \sqrt{wx^2})^2$ is decreasing if $x^2 \ge 4w/(1+w)^2$. Then, applying Cauchy--Schwarz inequality, we have
\begin{equation}
\Var[\widehat q_\sMFMC^{(1)}] \le \frac1N \left( \sum_{s=1}^S \lambda(A_s) \Var^\mu[\Q(X) | X \in D_s] \right) \left( \sum_{s=1}^S \lambda(A_s) \left( \sqrt{1 - \rho_s^2} + \sqrt{w\rho_s^2} \right)^2 \right),
\end{equation}
which, due to the concavity of the function $f$ and from Jensen's inequality, leads to
\begin{equation}
\begin{aligned}
\Var[\widehat q_\sMFMC^{(1)}] &\le \frac1N \left( \sum_{s=1}^S \lambda(A_s) \Var^\mu[\Q(X) | X \in D_s] \right) \\
&\hspace{2cm}\times \left( \sqrt{1 - \left( \sum_{s=1}^S \lambda(A_s) \rho_s \right)^2} + \sqrt{w \left( \sum_{s=1}^S \lambda(A_s) \rho_s \right)^2} \right)^2 \\
&= \frac1N \left( \sum_{s=1}^S \lambda(A_s) \Var^\mu[\Q(X) | X \in D_s] \right) \left( \sqrt{1 - \bar\rho^2} + \sqrt{w\bar\rho^2} \right)^2.
\end{aligned}
\end{equation}
Using again the law of total variance and the fact that the function $f$ is decreasing gives statement $(i)$, which completes the proof.
\end{proof}

\begin{remark} \label{rem:variance_MF}
In \cref{pro:variance_MF}, the condition for allocation (1) is weaker than the condition for allocation (2), but allocation (2) is easier to apply, since it only requires the probability mass of each strata. Moreover, we notice that \cref{pro:variance_MF} only provides sufficient conditions for variance reduction. In particular, a smaller variance can also be obtained even if the assumptions are not satisfied.
\end{remark}
%
The heuristic algorithm proposed in \cref{sec:heuristic} can still be applied in the context of stratified multifidelity estimators.
%
However, at each iteration, one must remember to always multiply the variance $\widetilde\sigma$ of the high-fidelity model in each stratum by a coefficient $\widetilde\eta$ given by
\begin{equation}
\widetilde\eta = \left( \sqrt{1 - \widetilde\rho^2} + \sqrt{w \widetilde\rho^2} \right)^2,
\end{equation}
which depends on the correlation $\widetilde\rho$ in the stratum and quantifies the variance reduction.

