The semantics of an $m$-PTAR $\A=(Q,\Sigma,q_0,\Delta,C)$ is defined as follows. We denote by $\textsc{ID}$ the set $Q\times \Nat^m$ of \emph{automaton configurations}, each consisting of a state and a \emph{counter configuration} from $\Nat^m$. For each transition $\tau\in\Delta$ we let $\Rightarrow^\tau$ be the binary relation on the set $T_\Sigma(\textsc{ID})$ such that for each $\zeta_1,\zeta_2\in T_\Sigma(\textsc{ID})$ we have
\[\zeta_1\Rightarrow^\tau\zeta_2\]
if there are $\hat\zeta\in C_\Sigma(\textsc{ID},X_1)$, $\hat\zeta_1,\hat\zeta_2\in T_\Sigma(\textsc{ID})$ such that $\zeta_1=\hat\zeta\cdot\hat\zeta_1$, $\zeta_2=\hat\zeta\cdot\hat\zeta_2$, and either
\begin{itemize}
    \item $\tau=q\to \sigma(q_1(d_1),\ldots, q_n(d_n))$ for some $n\geq 1$, $\hat\zeta_1=(q,w)$, and $\hat\zeta_2=\sigma((q_1,w_1),\ldots,(q_n,w_n))$ where, for each $i\in[n]$, $w_i=w+ d_i$ if $d_i\neq\reset$ and $w_i=\bm{0}$ otherwise, or
    \item $\tau=q\to\alpha$ for some $\alpha\in\Sigma^{(0)}$, $\hat\zeta_1=(q,w)$, $w\in C$, and $\hat\zeta_2=\alpha$.
\end{itemize}
The \emph{computation relation of $\A$} is the binary relation $\Rightarrow_\A=\bigcup_{\tau\in\Delta}\Rightarrow^\tau$. A \emph{computation} is a sequence $t=\zeta_0\Rightarrow^{\tau_1}\zeta_1\ldots\Rightarrow^{\tau_n}\zeta_n$ (sometimes abbreviated as $\zeta_0\Rightarrow^{\tau_1\ldots\tau_n}\zeta_n$) such that $n\in\Nat$, $\zeta_0,\ldots,\zeta_n\in T_\Sigma(\textsc{ID})$, $\tau_1,\ldots,\tau_n\in \Delta$, and $\zeta_{i-1}\Rightarrow^{\tau_i}\zeta_i$ for each $i\in[n]$. We say that the $\emph{length}$ of $t$ is $n$. We call $t$ \emph{successful on $\xi\in T_\Sigma$} if $\zeta_0=(q_0,\bm{0})$ and $\zeta_n=\xi$; the set of all successful computations of $\A$ on $\xi$ is denoted by $\compA{\xi}$. The \emph{language recognized by $\A$} is the set $\L(\A)=\{\xi\in T_\Sigma\mid \compA{\xi}\neq\emptyset\}$.

\paragraph{} Now we consider an example showing the capability of non-global Parikh tree automata to check a semi-linear property for each path in a tree.

\begin{example}\label{L-ab}
    Let $\Sigma=\{a^{(2)},b^{(2)},\#^{(0)}\}$. We consider the tree language $L_{ab}$ containing all trees $\xi$ such that the word of labels of each complete path in $\xi$ is of the form $a^n b^n\#$ for some $n\geq 1$, i.e.,
    \[L_{ab}=\{\xi\in T_{\Sigma}\mid \forall \pi\in\mathrm{paths}(\xi): \xi(\pi)\in\{a^nb^n\#\mid n\geq 1\}\}\,.\]

    This tree language can by recognized by the
    2-PTA $\A=(Q,\Sigma,q_a,\Delta,C)$ where $Q=\{q_a,q_b\}$, $C=\{(i,i)\mid i\geq 1\}$, and $\Delta$ contains the transitions
    \[\tau_{a,1}\colon\ q_a\to a(q_a(1,0),q_a(1,0))\qquad \tau_{a,2}\colon\ q_a\to b(q_b(0,1),q_b(0,1))\]
    and 
    \[\tau_{b,1}\colon\ q_b\to b(q_b(0,1),q_b(0,1))\qquad \tau_{b,2}\colon\ q_b\to \#\ .\]
    The intuition behind this automaton is quite easy: for each $a$ it reads, the first counter component is increased by $1$ and for each $b$ it reads, the second counter component is increased by $1$. Finally, $\#$ can only be computed if the value of the first and the second component is equal. This process becomes clear if we look at a part of some computation for $a(b(\#,\#),b(\#,\#))\in L_{ab}$: let us consider a computation of the form
    \begin{align*}
    (q_a,(0,0))&\Rightarrow^{\tau_{a,1}}a\bigl((q_a,(1,0)),(q_a,(1,0))\bigr)\\&\Rightarrow^{\tau_{a,2}}a\bigl(b((q_b,(1,1)),(q_b,(1,1))),(q_a,(1,0))\bigr)\\
    &\Rightarrow^{\tau_{b,2}}a\bigl(b(\#,(q_b,(1,1))),(q_a,(1,0))\bigr)\Rightarrow^* a(b(\#,\#),b(\#,\#))\,.
    \end{align*}
    Observe that in the third step of the computation, from the automaton configuration $(q_b,(1,1)))$ the application of $\tau_{b,2}$ to compute the leaf $\#$ is allowed only because $(1,1)\in C$.
    \exqed
\end{example}

\begin{remark}\label{remark}
We note that the tree language $L_{ab}$ is a \emph{context-free tree language}: it is a simple observation that the set of path words occurring in its trees is context-free and, thus,   $L_{ab}$ can be recognized by a pushdown tree automaton. However, we can easily extend Example \ref{L-ab} to paths of the form $a^nb^nc^n\#$ by using a third counter -- the resulting tree language would not be context-free anymore.
\end{remark}

\subsection{Restrictions of PTAR}


If $\reset$ does not occur in the transitions of $\A$, we call $\A$ an $m$-PTA. Moreover, we say that $\A$ is \emph{linear} if for each transition $q\to \sigma(q_1(d_1),\ldots, q_n(d_n))$ in $\Delta$ there is at most one $i\in[n]$ with $d_i\in\Nat^m$ and for all $j\neq i$ we have $d_j=\reset$, i.e., at each node the storage is either completely reset or passed to exactly one child.

