\subsection{Complexity bounds on general \texorpdfstring{\eqref{eq:OCFP}}{}}
\label{sec:generalocp}
Once it is shown the complexity of SOCP, the proof can be modified to derive the complexities of more general cases.

\begin{theorem}\label{th:complexgc}
Let $p=\frac{r}{s} \in \Q$, with $r > s\in \N^*$ and $\gcd(r,s)=1$. 
The feasibility of \eqref{eq:OCFP} can be tested in $\min\{[r(m+n)]^{O(n)}, m(rn)^{O(n^2)}\}$ arithmetic operations over $\bits\min\{[r(m+n)]^{O(n)}, (rn)^{O(n^2)}\}$-bit numbers.
\end{theorem}

\begin{proof}
It is enough to follow the proof of Theorem \ref{th:socpcomplexity}, while relying on Corollary \ref{coro:socpcomplexity} instead of Theorem  \ref{th:complexity}, selecting $R=R(p,n,m,\bits)$ \eqref{eq:R}, and replacing the sentence \eqref{eq:violated} by
%
    \begin{multline*}
    V_I^j:= \forall (\x,z),(\y,w)\in \R^{n+1} \; \forall \theta,\rho \in \R \{ \{
    (\lp{\x}{p}\leq z)\wedge (\lp{\y}{p}\leq w)\wedge S_I(\x,z,\theta)\\
     \wedge [S_I(\y,w,\rho)\Longrightarrow(\theta\leq \rho)]\wedge [S_I(\y,w,\theta)\Longrightarrow (\norme{(\x,z)}^2\leq \norme{(\y,w)}^2)]\}\\
    \Longrightarrow (\f^T_j\x+g_jz> h_j+\theta)\}.
    \end{multline*}

    By Theorem \ref{th:exreprs} the membership of $(\x,z)$ in $\K^n_p$ can be expressed by the formula \eqref{eq_gpcf} where $\lhd$ stands for $\leq$. 
    Then $V_I^j$ is a sentence involving $2$ quantifiers, $O(n)$ polynomial inequalities of degree at most $r$ in $O(n^2)$ variables. 
    The value of $B$ remains unchanged. 
    So for fixed dimension, Clarkson's algorithm yields a better bound.
\end{proof}
