\begin{theorem}\label{th:height}
    Given an optimal basis $S$ of \eqref{eq:discrepancy}, in $(rn)^{O(n\min\{m,n\})}$ operations over $\bits(rn)^{O(n\min\{m,n\})}$-bit numbers we can find a system of univariate polynomial inequalities with integer coefficients such that $\theta^*$ is the only real solution of the system. In particular, $\theta^*$ is a root of a nontrivial polynomial $p(\theta)\in \Z[\theta]$ such that $\log \height (p)=\bits(r n)^{O(n\min\{m,n\})}$.
\end{theorem}

\begin{proof}
    Assume without loss of generality that the given basis $S$ coincides with $M$. In particular, $m\leq n+1$. From Von Neumman's minimax theorem and \eqref{eq:min2}, it follows that for $R\geq 0$
%
    \begin{multline*}
        \theta^*=\dmin_{(\x,z)\in \K^n_p(R)}\dmax_{\La\in \Delta_m} \dsum_{i=1}^m \lambda_i(\f_i^T\x + g_iz - h_i) \\
        =\dmax_{\La\in \Delta_m}\dmin_{(\x,z)\in \K^n_p(R)} \left\{\left(\dsum_{i=1}^m\lambda_i\f_i^T\right)\x + \left(\dsum_{i=1}^m \lambda_i g_i\right)z - \dsum_{i=1}^m \lambda_i h_i\right\} \\
        =\dmax_{\La\in \Delta_m}\left\{ \min\left[0,R\left(\dsum_{i=1}^m \lambda_i g_i - \lp{\dsum_{i=1}^m\lambda_i\f_i}{q}\right)\right]  - \dsum_{i=1}^m \lambda_i h_i \right\}.
    \end{multline*}
%
    Consider the formula
%
    \begin{equation*}
        \Lambda(\theta):= \forall \La\in \Delta_m \left\{ \min\left[0,R\left(\dsum_{i=1}^m \lambda_i g_i - \lp{\dsum_{i=1}^m\lambda_i\f_i}{q}\right)\right]  - \dsum_{i=1}^m \lambda_i (h_i+\theta)\leq 0 \right\},
    \end{equation*}
%
    where $R=R(p,n,m,\bits)$ \eqref{eq:R}. This formula states that $\theta\geq \theta^*$, and it can be written as follows
%
    \begin{multline*}
    \forall \La \in \R^m \; \exists (\t,w) \in \R^{n+1} \Bigg\{ \left[
    \lambda_1 \geq 0, \ldots, \lambda_m \geq 0, \quad \sum_{i=1}^m \lambda_i = 1
    \right] \implies \\
    \Bigg\{\Bigg[t_1\geq 0,\ldots, t_n\geq0, \bigwedge_{j=1}^n \left[\left[
        \left( \sum_{i=1}^m \lambda_i f_{ij} \right)^r = w^s t_j^{r-s}
    \right]\vee \left[
        -\left( \sum_{i=1}^m \lambda_i f_{ij} \right)^r = w^s t_j^{r-s}
    \right]\right], \\ \sum_{j=1}^n t_j = w \Bigg]\wedge 
    \left[\left(\sum_{i=1}^m \lambda_i (h_i+\theta)\geq 0 \right)\vee \left(R \left( \sum_{i=1}^m \lambda_i g_i - w \right) - \sum_{i=1}^m \lambda_i (h_i+\theta) \leq 0\right)\right] 
    \Bigg\}\Bigg\}.
    \end{multline*}
%
Now $\theta^*$ is the only real solution of $\Lambda^*(\theta):= \forall \theta'\in \R \{\Lambda(\theta)\wedge [\Lambda(\theta')\Longrightarrow (\theta \leq \theta^*)]\}$. 
By consecutively applying Theorem \ref{prop:renegarfree} to $\Lambda(\theta)$ and $\Lambda^*(\theta)$, the latter formula can be transformed into a quantifier free formula $\Lambda^{**}(\theta)$. 
%
This requires $[r(m+n)]^{O(mn)}\leq (rn)^{O(n\min\{m,n\})}$ operations with $\max\{\bits,\log R\}[r(m+n)]^{O(mn)}\leq \bits(rn)^{O(n\min\{m,n\})}$-bit numbers. 
The formula $\Lambda^{**}(\theta)$ is composed of univariate polynomial relations $p(\theta)\lhd 0$, where $\lhd\in\{\leq,<,=,\neq,>,\geq\}$. Since $\theta^*$ is the only real solution of $\Lambda^{**}(\theta)$, this formula can be transformed into an equivalent system of polynomial inequalities, which must contain a polynomial $p$ such that $p(\theta^*)=0.$
%
\end{proof}
\begin{theorem}\label{th:height2}
Given $r\in 2\N^*$, let $p=\frac{r}{r-1}$. 
Then we can replace the bounds of Theorem \ref{th:height} by $(r\min\{m,n\})^{O(\min\{m,n\})}$ and $\bits(r\min\{m,n\})^{O(\min\{m,n\})}$.
\end{theorem}

\begin{proof}
It is enough to follow the proof of Theorem \ref{th:height} by relying on Theorem \ref{th:bounds2} instead of Theorem \ref{th:bounds}, and writing the formula $\Lambda(\theta)$ as 
%
    \begin{multline*}
        \forall \La \in \R^m \; \exists w \in \R \Bigg\{ \left[
        \lambda_1 \geq 0, \ldots, \lambda_m \geq 0, \quad \sum_{i=1}^m \lambda_i = 1
        \right] \implies 
        \Bigg\{\Bigg[
        \sum_{j=1}^n \left( \sum_{i=1}^m \lambda_i f_{ij} \right)^r  = w^r, w\geq 0 \Bigg] \wedge \\\left[\left(\sum_{i=1}^m \lambda_i (h_i+\theta)\geq 0 \right)\vee \left(R \left( \sum_{i=1}^m \lambda_i g_i - w \right) - \sum_{i=1}^m \lambda_i (h_i+\theta) \leq 0\right)\right] \Bigg\}\Bigg\}.
        \end{multline*}
%    
\end{proof}
\begin{remark}
    The minimal polynomial of an algebraic number $\alpha$ is the primitive irreducible polynomial $p\in \Z[x]$ such that $p(\alpha)=0$ and the leading coefficient of $p$ is positive. 
    The $\height$ of $\alpha$ is the height of its minimal polynomial. 
    Theorem \ref{th:height2} and the well-known Mignotte's inequality recalled in Proposition \ref{prop:height} show that $\log \height (\theta^*) = \bits(r\min\{m,n\})^{O(\min\{m,n\})}$.
\end{remark}
Theorem~\ref{th:height} and Theorem~\ref{th:height2} immediately imply Theorem \ref{th:discrepancy}. 
\begin{proof}[Proof of Theorem \ref{th:discrepancy}]
Since the problem \eqref{eq:OCFP} is infeasible, one has $\theta^*>0$. 
Theorem \ref{th:height} and Theorem \ref{th:height2} imply that the positive algebraic number $\theta^*$ is a root of a nontrivial polynomial $p \in\Z[x]$ with integer coefficients of bit sizes $\bits(rn)^{O(n\min\{m,n\})}$ and $\bits(r\min\{m,n\})^{O(\min\{m,n\})}$, respectively. 
Proposition \ref{prop:height} implies that $\theta^*\geq \frac{1}{1+\height(p)}$, yielding the desired result.
\end{proof}
\begin{remark}
    If $p=r\in 2\N^*$, then one can write the formula $\Lambda(\theta)$ from the proof of Theorem \ref{th:height} as
%
    \begin{equation}
        \forall (\x,z)\in \R^{n+1}\left\{\bigwedge_{i\in M} [\f_i^T\x+g_iz-(h_i+\theta)\leq 0], \dsum_{j=1}^bx_j^r\leq z^r, z\geq 0, \norme{(\x,z)}^2\leq R^2\right\},
    \end{equation}
with $\log R\leq \bits(\min\{m,n\}r)^{O(n)}$. The bounds of Theorems \ref{th:discrepancy} and \ref{th:height} become $(\min\{m,n\}r)^{O(n)}$ and $\bits(\min\{m,n\}r)^{O(n)}$.
\end{remark}
\section{Generalization to several \texorpdfstring{$p$}{}-order cone constraints}
\label{sec:multi}
{
In this section, we generalize our results to the case of more than one $p$-order cone constraints. 
Namely, given $d \in \N^*$ and $n_1, \dots, n_d \in \N^*$, we consider the norm  constraints $(\x_k,z_k) \in \K_p^{n_k},  k=1,\ldots,d$. 
With $n:=n_1+\cdots+n_d$, let $(\x,\z):=(\x_1;\ldots;\x_d;z_1;\ldots;z_d) \in \R^{n+d}$ be the full vector of variables. 
Given $p=\frac{r}{s} \in \Q$, with $r > s\in \N^*$ and $\gcd(r,s)=1$, we consider the  $p$-order feasibility problem that consists of determining whether there exists a real vector $(\x,\z) \in \R^{n+d}$ such that
\begin{align}
\label{eq:multiocp}
     F_1 \x_1 + G_1z_1+\cdots + F_d\x_d+ G_dz_d \leq H, &\nonumber\\
     (\x_k,z_k) \in \K_p^{n_k}, \; k=1,\ldots,d, &
\end{align}
where $F_k \in \Z^{m\times n_k}, G_k, H \in \Z^{m}$ for $m \in \N^*$. 
We assume that all tuples $(\x_k,z_k)$ are independent. 
The above problem involves $n+d$ variables and $m+d$ constraints. 
If this independence assumption does not hold then one can always introduce additional variables satisfying it and encode the dependencies via linear equality constraints. 

The result of Theorem~\ref{th:complexity} can be generalized as follows. 
\begin{theorem}
\label{th:multicomplexity}
Let us consider \eqref{eq:multiocp} and assume that all tuples $(\x_k,z_k)$ are independent. \\
If $p=\frac{r}{s} \in \Q$, with $r > s\in \N^*$ and $\gcd(r,s)=1$, then the feasibility of \eqref{eq:multiocp} can be tested in $[(m+n+d)r]^{O(n+d)}$ arithmetic operations over $\bits[(m+n+d)r]^{O(n+d)}$-bit numbers.\\
If $p=r\in 2\N^*$ then the feasibility of \eqref{eq:multiocp} can be tested in $[(m+d)r]^{O(n+d)}$ arithmetic operations over $\bits[(m+d)r]^{O(n+d)}$-bit numbers.\\
If $p=\frac{r}{r-1}$ with $r\in 2\N^*$ then the feasibility of \eqref{eq:multiocp} can be tested in $[(m+d)r]^{O(md^2)}$ arithmetic operations over $\bits[(m+d)r]^{O(md^2)}$-bit numbers.
\end{theorem}
\begin{proof}
We sketch the proof by emphasizing the main differences w.r.t. the single constraint case. 
\begin{itemize}
\item Thanks to the independence assumption, Equation \eqref{eq:min} in Lemma \ref{lemma:ptheq} can be generalized as follows:
    \begin{equation*}
        \dmin_{\genfrac{}{}{0pt}{}{(\x_k,z_k)\in \K^{n_k}_p:}{k=1,\ldots,d} }\left\{\dsum_{k=1}^d (\f_k^T\x_k + g_kz_k) : z_1=R_1,\dots,z_d=R_d\right\}=\dsum_{k=1}^dR_k(g_k-\lp{\f_k}{q}),
    \end{equation*}
where $\|\cdot\|_q$ is the dual of the $\|\cdot\|_p$ norm, i.e., $q$ is such that $\frac{1}{p} + \frac{1}{q} = 1$.     
 \item  Lemma \ref{th:boundseven} becomes $\norme{(\x,\z)}\leq R$, where $\log R = \bits [(\min\{m,n\}+d)r]^{O(n+d)}$.

\item    In Theorem \ref{th:bounds}, $\Theta(R)$ is replaced by  
\begin{align*}
        \Theta(R_1,\ldots, R_d)& := \dmin_{
        \genfrac{}{}{0pt}{}{(\x_k,z_k)\in \Omega_{R_k}:}{k=1,\ldots,d}
        }\max\left\{\dsum_{k=1}^d \left(\f_{1k}^T\x_k + g_{1k}z_k\right)-h_1,\ldots, \dsum_{k=1}^d \left(\f_{mk}^T\x_k + g_{mk}z_k\right)-h_m\right\}, \\
        \text{with } \Omega_{R_k}& =\{(\x,z)\in \K^{n_k}_p : z=R_k\}. 
    \end{align*}

    For any $R_1,\ldots, R_d\geq 0$ and considering $\Delta_m$ as in \eqref{def:simplex}, 
%
    \begin{multline*}
        \Theta(R_1,\ldots, R_d)=\dmin_{\genfrac{}{}{0pt}{}{(\x_k,z_k)\in \Omega_{R_k}:}{k=1,\ldots,d}}\dmax_{\La\in \Delta_m} \dsum_{i=1}^m \lambda_i\left(\dsum_{k=1}^d \left(\f_{ik}^T\x_k + g_{ik}z_k \right)-h_i\right) \\
        =\dmax_{\La\in \Delta_m}\dmin_{\genfrac{}{}{0pt}{}{(\x_k,z_k)\in \Omega_{R_k}:}{k=1,\ldots,d}} \left[\dsum_{k=1}^d \left( \left(\dsum_{i=1}^m\lambda_i\f_{ik}^T\right)\x_k + \left(\dsum_{i=1}^m \lambda_i g_{ik}\right)z_k \right) - \dsum_{i=1}^m \lambda_i h_i\right] \\
        =\dmax_{\La\in \Delta_m}\left[ \dsum_{k=1}^d R_k\left(\dsum_{i=1}^m \lambda_i g_{ik} - \lp{\dsum_{i=1}^m\lambda_i\f_{ik}}{q}\right)  - \dsum_{i=1}^m \lambda_i h_i \right].
    \end{multline*}
Then $\Phi(R)$ is replaced by  
    \begin{equation*}
        \Phi(R_1,\ldots, R_d) := \forall \La \in \Delta_m \left\{ \dsum_{k=1}^d R_k\left(\dsum_{i=1}^m \lambda_i g_{ik} - \lp{\dsum_{i=1}^m\lambda_i\f_{ik}}{q}\right)  - \dsum_{i=1}^m \lambda_i h_i\leq 0 \wedge (R_1\geq 0, \ldots, R_d\geq 0)\right\}.
    \end{equation*}
    By Theorem \ref{th:exreprs}, $\Phi(R)$ can be rewritten in the standard form \eqref{eq:sf} as follows

    \begin{multline*}
    \forall \La \in \R^m \; \exists (\t_k,w_k)_{k=1}^d \in \R^{n+d} \Bigg\{ \Bigg\{ \left[
    \lambda_1 \geq 0, \ldots, \lambda_m \geq 0, \quad \sum_{i=1}^m \lambda_i = 1
