        \texttt{XGBoost}                    & $\sim$ 0.066              & $\sim$ 330            \\
        \texttt{LightGBM}                   & $\sim$ 0.069              & (214–754)             \\
        \texttt{1DJuLiNet}              & 124.42                    & --                    \\
        \texttt{1DJuLiNetSingularity}    &  45.99                    & --                    \\
