\obsTwoLayerNonLeafDeg*
\label{obs:2-layer:non-leaf-degree*}

\begin{proof}
    Suppose that $G$ admits a 2-layer $k$-planar drawing $D$.
    Let $v$ be a vertex of $G$ with more than $2k+2$ non-leaf neighbors.
    Without loss of generality, we assume that $v \in X$.
    Let $y_1, \dots, y_{d} \in Y$ be the non-leaf neighbors of $v$ appearing in this order in~$D$, and let $e_i$ denote the edge $\{v, y_i\}$ for $1 \le i \le d$.
    Since $y_{k + 2}$ is not a leaf, it has an incident edge other than~$e_i$.
    This edge has a crossing with either each of $e_1, \dots, e_{k+1}$ or each of $e_{k+3}, \dots, e_{d}$, contradicting the $k$-planarity of $D$.
    Hence, we have the following observation.
\end{proof}

\lemTwoLayerDegreeReduction*
\label{lem:2-layer:degree-reduction*}

\begin{proof}
  The forward implication is immediate since $G-y$ is a subgraph of $G$.

  Now suppose that $G-y$ has a 2-layer $k$-planar drawing $D' = (<_X, <_Y)$.
  Let $y_1, \dots, y_{d}$ be the neighbors of $v$ appearing in this order in $<_Y$, and, for $i \in [d]$, let $e_i = \{v, y_i\}$.
  Observe that $e_{k + 2}$ has no crossings, as otherwise there is an edge that has a crossing with either each of $e_1, \dots, e_{k+1}$ or each of $e_{k+3}, \dots, e_{d}$.
  Moreover, $y_{k + 2}$ is a leaf, as otherwise every edge incident to $y_{k + 2}$ and different from $e_{k+2}$ involves more than $k$ crossing. 
  Thus, we can insert~$y$ immediately to the left of $y_{k + 2}$ in $D'$ without introducing a new crossing.
  Hence, the resulting drawing is a 2-layer $k$-planar drawing of $G$.
\end{proof}

\lemTLayerIfFarEnoughTheyDontCross*
\label{lem:2-layer:if-far-enough-they-dont-cross*}
\begin{proof}
    Suppose that $y >_Y y'$, which means that $e$ and $f$ cross.
    For every $t$ with $p < t < q$, there is at least one edge incident to vertex $x_t$, as $X$ contains no isolated vertices.
    Each of these at least $\ell=2k$ edges crosses~$e$ or~$f$ (which cross each other).
    Thus, $e$ or $f$ has more than $k$ crossings~-- a contradiction.
