    \centering
    \subfloat[]{\includegraphics[width=6cm]{supplementary_figures/empirical_dilem_individ_6_6.pdf}}
    \subfloat[]{\includegraphics[width=6cm]{supplementary_figures/empirical_dilem_group_6_6.pdf}}
