To narrow the search space, the following three additional conditions are imposed:
\begin{enumerate}[(1)]
	\item since \cite{charpin2009does} has already investigated the case where $k=1$, to avoid obtaining redundant results, it is assumed that $k>1$. 
	\item $d_2$ is the representative element of all positive integers less than $q^l-1$ under the cyclotomic equivalence, and $\tr_{q^l/q}(x^{d_2}) \ne 0$.
	\item Regarding the range of $d_1$, only cases where $d_1$
	within the range $[1,q^l-2]$ is a divisor of $q^l-1$ are considered based on the following lemma.
\end{enumerate} 
\begin{Lemma}\label{divisor}
	Let $\gcd(d_1,q^l-1)=s$. $f(x)=cx^{d_1}+\tr_{q^l/q}(x^{d_2})$ is $2$-to-$1$ if and only if $g(x)=f(x^t)=x^s+\tr_{q^l/q}(x^{d_2t})$ is $2$-to-$1$ where $d_1t\equiv s \pmod {q^l-1}$, $s$ is a divisor of $q^l-1$.
\end{Lemma}
\begin{proof}
	Let $(d_1,q^l-1)=s$, $(t,q^l-1)=1$. Then $(td_1,q^l-1)=s$, $$f\left(x^t\right)=cx^{td_1}+\tr_{q^l/q}\left(x^{d_2t}\right)=cx^s+\tr_{q^l/q}\left(x^{d_2t}\right).$$ Since $g(x)=f(x^t)$, $f(x)$ is QM-equivalent to $g(x)$. Due to Definition \ref{QM}, $f$ is $2$-to-$1$ if and only if $g$ is $2$-to-$1$.
\end{proof}


Then we obtain all $2$-to-$1$ polynomials over $\gf_{q^l}$ of the form $cx^{d_1}+\tr_{q^l/q}(x^{d_2})$ with $q=2^k$, $d_1,d_2 \in[1,q^l-2]$, $kl<14$, $c \in \gf_{q^l}^*$ and $k,l \in \mathbb{N}^+$ in Table \ref{3-1}. The ``Reference" column in the table indicates that this dataset served as an illustrative example for the theorem cited in the ``Reference". The data illustrated that there does not exist a $2$-to-$1$ mapping of the form $cx^{d_1}+\tr_{q^l/q}(x^{d_2})$ when $d_1 \ne 1$. Therefore, we consider the form $cx+\tr_{q^l/q}(x^d)$. All examples in Table \ref{3-1} have been generalized into infinite classes.


\begin{Th}
    \label{3.2}
	Let $l$ be an odd positive integer, $q=2^k$, $k \in \mathbb{N}$, $c\in\mathbb{F}_q^\ast$. Then
	\begin{enumerate}[1)]
		\item $f(x)=cx+\tr_{q^l/q}(x^{q+1})$;\label{q+1}
		\item $f(x)=cx+\tr_{q^l/q}(x^{2q+2})$, where $k$ is odd;\label{2q+2} 
		\item $f(x)=cx+\tr_{q^l/q}(x^{q^2+1})$ \label{q^2+1}
	\end{enumerate}
	are $2$-to-$1$ over $\mathbb{F}_{q^l}$. 
\end{Th}
\begin{proof}
    Since the proof techniques for these cases are analogous, we present a detailed demonstration for the first case as a representative example. 
    According to the definition of $2$-to-$1$ mappings, we show that for any $a\in \gf_{q^l}$, the equation $f(x)=a,$ i.e.,
	\begin{eqnarray}\label{1}
		cx+\tr_{q^l/q}(x^{q+1})=a
	\end{eqnarray}
	has 0 or 2 solutions in $\gf_{q^l}$.

	Let $u=cx+a$. Then $u=\tr_{q^l/q}(x^{q+1})\in \gf_{q}$ and $x=\frac{u+a}{c}$ since $c\ne0$. Moreover, since $u\in \gf_{q}$ and $c\in \gf_q^*$, $$x^{q+1}=\left(\frac{u+a}{c}\right)^{q+1}=\frac{u^2+u(a+a^q)+a^{q+1}}{c^2}.$$

	Plugging the above equation into Eq. (\ref{1}), we get 
	$$u=\tr_{q^l/q}\left(\frac{u^2+u(a+a^q)+a^{q+1}}{c^2}\right)=\frac{u^2}{c^2}+\tr_{q^l/q}(a+a^q)\frac{u}{c^2}+\frac{\tr_{q^l/q}(a^{q+1})}{c^2},$$
	where the second equality holds due to Lemma \ref{trace}(4) and $l$ being odd. Note that for any $a\in\gf_{q^l}$, $\tr_{q^l/q}(a+a^q)=0$, thus the above equation becomes
	$$u=\frac{u^2}{c^2}+\frac{\tr_{q^l/q}(a^{q+1})}{c^2}.$$
	That is, 
	\begin{eqnarray}\label{2}
		u^2+c^2u+\tr_{q^l/q}(a^{q+1})=0.
	\end{eqnarray}

	In case of $c\ne0$, Eq. (\ref{2}) has 0 or 2 solutions in $\gf_{q}$. Hence $f(x)=a$ has 0 or 2 solutions in $\gf_{q^l}$. That is to say, $f(x)$ is $2$-to-$1$ over $\gf_{q^l}$.
\end{proof}
\begin{Th}
\label{3.3}
	Let $k$ and $l$ be odd positive integers, $q=2^k$ and $c\in \gf_{q}^* $. Then
	\begin{enumerate}[1)]
		\item $f(x)=cx+\tr_{q^l/q}(x^6)$;\label{x^6}
		\item $f(x)=cx+\tr_{q^l/q}(x^{4q+2})$; \label{4q+2}
		\item $f(x)=cx+\tr_{q^l/q}(x^{2q+4})$ \label{2q+4}
	\end{enumerate}
	are $2$-to-$1$ over $\gf_{q^l}$. 
\end{Th}
\begin{proof}
    Since the proof techniques for these cases are analogous, we present a detailed demonstration for the first case as a representative example.
	According to Lemma \ref{$2$-to-$1$}, it suffices to show that for any $a \in \gf_{q^l}$, the equation 
	$$f(x+a)+f(a)=0,$$ 
	i.e., 
	\begin{eqnarray}\label{3}
		cx+\tr_{q^l/q}(x^6+a^2x^4+a^4x^2)=0
	\end{eqnarray} 
	has 2 solutions in $\gf_{q^l}$.
	According to Eq. (\ref{3}), we get $cx=\tr_{q^l/q}(x^6+a^2x^4+a^4x^2)\in\gf_{q}$ and $x\in \gf_{q}$ since $c\in\gf_{q}^*$. 

    From Lemma \ref{trace}(4),
	$$x^6+\tr_{q^l/q}(a^2)x^4+\tr_{q^l/q}(a^4)x^2+cx=0,$$
	where $l$ is odd and $x\in \gf_{q}$.
	Thus $x=0$ or 
	\begin{eqnarray}\label{4}
		x^5+\tr_{q^l/q}(a^2)x^3+\tr_{q^l/q}(a^4)x=c.
	\end{eqnarray}

	We notice that $$x^5+\tr_{q^l/q}(a^2)x^3+\tr_{q^l/q}(a^4)x=D_5(x,\tr_{q^l/q}(a^2))$$ is a Dickson polynomial of degree 5. Recalling that $k$ is odd, $\mathrm{gcd}(5,q^2-1)=1$, and from Lemma \ref{gcd}, $D_5(x,\tr_{q^l/q}(a^2))$ permutes $\gf_{q}$. That is, Eq. (\ref{4}) only has one solution in $\gf_{q}$, and the solution is not 0 since $c \ne 0$. Therefore, Eq. (\ref{3}) has two solutions in $\gf_{q^l}$ and then $f(x)$ is $2$-to-$1$ over $\gf_{q^l}$.
\end{proof}
\begin{Th}
	\label{l=2,2q+4}
	Let $k$ be an odd positive integer and $q=2^k$, $c \in \gf_{q^2}^*$ satisfies $c^{q-1}=\omega$ with $\omega\in \gf_{2^2} \backslash \gf_2$. Then $f(x)=cx+\tr_{q^2/q}(x^{2q+4})$ is $2$-to-$1$ over $\gf_{q^2}$.
\end{Th}
\begin{proof}
	According to Lemma \ref{$2$-to-$1$}, it suffices to show that for any $a\in \gf_{q^2}$, the equation $$f(x+a)+f(a)=0,$$ i.e.,
	\begin{eqnarray}\label{5}
		cx+\tr_{q^2/q}((x+a)^{2q+4}+a^{2q+4})=0
	\end{eqnarray}
	has two solutions in $\gf_{q^2}$.

	Let $y=x^{2q}$, $b=a^{2q}$. Plugging the above two equations into Eq. (\ref{5}), we get \begin{eqnarray}\label{6}
		cx+x^4y+x^4b+a^4y+x^2y^2+x^2b^2+a^2y^2=0.
	\end{eqnarray}

	Computing the sum of Eq. (\ref{6}) and its $q$th power, then $y=c^{2(1-q)}x^2$, implying $y=\omega^{-2}x^2$.
	Then from Eq. (\ref{6}), 
    \begin{eqnarray*}
        \left(\frac{\omega^2+1}{\omega^4}\right)x^6+\left(\frac{a^2}{\omega^4}+b\right)x^4+\left(\frac{a^4}{\omega^2}+b^2\right)x^2+cx=0.
    \end{eqnarray*}

	According to the properties of cubic primitive roots $\omega^2+\omega+1=0$, the above equation becomes $$x^6+(\frac{a^2}{\omega}+b)x^4+(\frac{a^4}{\omega^2}+b^2)x^2+cx=0.$$

    Obviously $x=0$, it only needed to prove for any $a\in \gf_{q^2}$, the equation 
	\begin{equation}
		x^5+\left(\frac{a^2}{\omega^4}+b\right)x^3+\left(\frac{a^4}{\omega^2}+b^2\right)x=c \label{7}
	\end{equation}
	has one solution in $\gf_{q^2}^*$.

	We notice that $x^5+\left(\frac{a^2}{\omega}+b\right)x^3+\left(\frac{a^4}{\omega^2}+b^2\right)x=D_5\left(x,\frac{a^2}{\omega}+b\right)$ is a Dickson polynomial of degree 5. Recalling that $k$ is odd, $\mathrm{gcd}(5,q^2-1)=1$, and from Lemma \ref{gcd}, $D_5\left(x,\frac{a^2}{\omega^4}+b\right)$ permutes $\gf_{q}$. That is, Eq. (\ref{7}) only has one solution in $\gf_{q}$, and the solution is not 0 since $c\ne 0$. Therefore, the Eq. (\ref{5}) has two solutions in $\gf_{q^2}$ and $f(x)$ is $2$-to-$1$ over $\gf_{q^2}$.
\end{proof}

\begin{Th}
    \label{Conj1}
	Let $k \equiv 1 \pmod 4$ and $q=2^k$, $c \in \gf_{q^2}^*$ satisfies $c^{q-1}=\omega$ with $\omega \in \gf_{2^2} \backslash \gf_2$. Then $f(x)=cx+\tr_{q^2/q}\left(x^{2^\frac{k+1}{2}+2}\right)$ is $2$-to-$1$ over $\gf_{q^2}$. 
\end{Th} 
\begin{proof}
    According to Lemma \ref{$2$-to-$1$}, it suffices to show that for any $a\in \gf_{q^2}$, the equation $$f(x+a)+f(a)=0,$$ i.e.,
	\begin{eqnarray}\label{3.5}
		cx+\tr_{q^2/q}\left(x^{2^{\frac{k+1}{2}}+2}+a^2x^{2^{\frac{k+1}{2}}}+a^{2^{\frac{k+1}{2}}}x^2\right)=0
	\end{eqnarray}
    has two solutions, i.e., one nonzero solution in $\gf_{q^2}$. In the following, we mainly consider the unique nonzero solution. 

    Let $$
    \begin{cases}
        y=x^{2^{\frac{k+1}{2}}}, z=y^{2^{\frac{k+1}{2}}}=x^{2q}, t=z^{2^{\frac{k+1}{2}}}=y^{2q}, t^{2^{\frac{k+1}{2}}}=x^4.\\
        u=a^{2^{\frac{k+1}{2}}}, v=u^{2^{\frac{k+1}{2}}}=a^{2q}, s=v^{2^{\frac{k+1}{2}}}=u^{2q}, s^{2^{\frac{k+1}{2}}}=a^4.
    \end{cases}
    $$
    Then we get $x^{2^{\frac{k+1}{2}}+2}=x^2y$, $x^{2^{\frac{k+1}{2}}}=y$, $a^{2^{\frac{k+1}{2}}}=u$, $(x^2y)^q=zt^{\frac{1}{2}}$, $(a^2y)^q=vt^{\frac{1}{2}}$, $(x^2u)^q=zs^{\frac{1}{2}}$. 

    From Eq. (\ref{3.5}), 
    \begin{eqnarray}\label{x1,y1}
        cx+x^2y+zt^{\frac{1}{2}}+a^2y+vt^{\frac{1}{2}}+ux^2+zs^{\frac{1}{2}}=0.
    \end{eqnarray}
    Raising Eq. (\ref{x1,y1}) to its $2^{\frac{k+1}{2}}$-th power, it leads to
    \begin{eqnarray}\label{x2,y2}
        c^{2^{\frac{k+1}{2}}}y+y^2z+tx^2+u^2z+sx^2+vy^2+a^2t=0.
    \end{eqnarray}

    According to Eq. (\ref{3.5}), we have $$cx=\tr_{q^2/q}\left(x^{2^{\frac{k+1}{2}}+2}+a^2x^{2^{\frac{k+1}{2}}}+a^{2^{\frac{k+1}{2}}}x^2\right) \in \gf_q,$$ and then $x^q=c^{1-q}x=\omega^2 x$. 

    Since $k \equiv 1 \pmod 4$, $z=x^{2q}=\omega x^2$, $t=\omega^{2^{\frac{k+1}{2}}}y^2=\omega^2y^2$. Plugging them into Eq. (\ref{x1,y1}) and Eq. (\ref{x2,y2}), we get 
   \begin{equation}
       \label{con1_eq1}
       cx+\omega x^2y+(a^{2q}\omega+a^2)y+(u^q\omega+u)x^2=0
   \end{equation}
 and 
 \begin{equation}
     \label{con1_eq2}
     c^{2^{\frac{k+1}{2}}}y+x^2y^2+(u^2\omega+u^{2q})x^2+(a^{2q}+a^2\omega^2)y^2=0,
 \end{equation}
 respectively. 

   From Eq. \eqref{con1_eq1}, we have $(\omega x^2 + a^{2q}\omega+a^2) y = cx + (u^q\omega+u)x^2$ and thus we need to discuss $\omega x^2 + a^{2q}\omega+a^2=0,$ i.e., $x=a^q+a\omega$ or not.  If $x=a^q+a\omega$ is a nonzero solution, then $a^q+a\omega\neq0$ and $c+(u^q\omega + u)(a^q+a\omega)=0$ by Eq. \eqref{con1_eq1}. Thus, in the following, we divide the proof into three cases: (I) $a^{2q}\omega+a^2=0$; (II) $a^{2q}\omega+a^2\neq0$ and $c+(u^q\omega + u)(a^q+a\omega)=0$; (III) $a^{2q}\omega+a^2\neq0$ and $c+(u^q\omega + u)(a^q+a\omega)\neq0$. 




(I)  When $a^{2q}\omega+a^2=0$, after raising it to its $2^{\frac{k+1}{2}}$-th power, we get $u^q+u\omega^2=0$. Then by Eq. \eqref{con1_eq2}, we have $c^{2^{\frac{k+1}{2}}}y+x^2y^2=0$, i.e., $x^{2^{\frac{k+1}{2}}+2}=c^{2^{\frac{k+1}{2}}}$. Note that $$\gcd\left( 2^{\frac{k+1}{2}}+2, 2^{2k}-1 \right)=1$$ since 
  $$\gcd\left(2^{2l}+1,2^{4l+1}-1\right) = \gcd\left( 2^{2l}+1, 2^{2l+1}+1 \right) = \gcd\left( 2^{2l}+1,1 \right) = 1$$
and 
$$\gcd\left(2^{2l}+1, 2^{4l+1}+1\right) = \gcd\left( 2^{2l}+1, 2^{2l+1}-1 \right) = \gcd\left( 2^{2l}+1,3 \right) = 1,$$
where $l=\frac{k-1}{4}$. Thus there exist a unique positive integer $d\le 2^{2k}-1$  such that  $d\cdot (2^{\frac{k+1}{2}}+2) \equiv 1\pmod { 2^{2k}-1}$ and thus from $x^{2^{\frac{k+1}{2}}+2}=c^{2^{\frac{k+1}{2}}}$, we get a unique nonzero solution $x_0=\left(c^{2^{\frac{k+1}{2}}}\right)^d$. Moreover, it is easy to check $x_0=\left(c^{2^{\frac{k+1}{2}}}\right)^d$ is exactly the unique nonzero solution of Eq. \eqref{3.5} in this case. 

(II) When $a^{2q}\omega+a^2\neq0$ and $c+(u^q\omega + u)(a^q+a\omega)=0$, then it is trivial that $x=a^q+a\omega$ is a nonzero solution of Eq. \eqref{con1_eq1}. By direct computations, we can find that $x=a^q+a\omega$ is exactly a nonzero solution of Eq. \eqref{3.5} in this case. If $x\neq a^q+a\omega$, then by Eq. \eqref{con1_eq1}, we have 
$$y=\frac{cx+(u^q\omega+u)x^2}{\omega x^2+a^{2q}\omega+a^2}.$$
Plugging it into Eq. \eqref{con1_eq2} and simplifying, we get 
\begin{equation}
    \label{con1_eq3}
    Ax = c^{2^{\frac{k+1}{2}}+1} \omega,
\end{equation}
where 
$$A = c^{2^{\frac{k+1}{2}}} (u^q+u\omega^2) + c^2\omega + (u^2\omega + u^{2q}) (a^{2q}+a^2\omega^2). $$
Plugging $c = (u^q\omega + u)(a^q+a\omega)$ into the expression of $A$, we have $A = c^{2^{\frac{k+1}{2}}} (u^q+u\omega^2)$ and then Eq. \eqref{con1_eq3} becomes $(u^q+u\omega^2) x = c\omega$, implying $x = a^q+a\omega$. Thus, Eq. \eqref{3.5} has exactly one nonzero solution. 

(III) When  $a^{2q}\omega+a^2\neq0$ and $c+(u^q\omega + u)(a^q+a\omega)\neq0$, then $\omega x^2+a^{2q}\omega+a^2\neq0$, and it suffices to consider Eq. \eqref{con1_eq3}. In the following, we show that $A\neq0$ in this case and thus $x=c^{2^{\frac{k+1}{2}}+1} \omega A^{-1}$ is the unique nonzero solution of Eq. \eqref{con1_eq3}. If $A=0$, i.e.,
\begin{equation}
    \label{con1_eq4}
    c^{2^{\frac{k+1}{2}}} (u^q+u\omega^2) + c^2\omega + (u^2\omega + u^{2q}) (a^{2q}+a^2\omega^2) = 0,
\end{equation}
then raising Eq. \eqref{con1_eq4} to its $2^{\frac{k+1}{2}}$-th power and simplifying, we get 
$$  c^{2^{\frac{k+1}{2}}} = c(a+a^q\omega^2) + (a^{2q}+a^2\omega^2) (u^q+u\omega).$$
Plugging it into Eq. \eqref{con1_eq4}, we have 
\begin{equation}
    \label{con1_eq5}
    c^2+ \omega (a^q+\omega a) (u^q + \omega^2 u) c + \omega^2 (u^q+\omega^2 u) (u^qa^2+a^{2q}u) = 0.
\end{equation}
Let $\Delta=a^q+\omega a.$ Then $u^q+\omega^2u = \Delta^{2^{\frac{k+1}{2}}}$ and $$u^qa^2 +a^{2q}u = u(a^{2q}+\omega^2a^2) + a^2 (u^q+\omega^2u) = u\Delta + a^2 \Delta^{2^{\frac{k+1}{2}}}.$$ Moreover, Eq. \eqref{con1_eq5} becomes 
\begin{equation}
    \label{con1_eq6}
    c^2+\omega \Delta^{2^{\frac{k+1}{2}}+1}c+\omega^2\Delta^{2^{\frac{k+1}{2}}}\left( u\Delta^2 + a^2 \Delta^{2^{\frac{k+1}{2}}} \right) = 0.
\end{equation}
Since 
$$  \frac{ \omega^2\Delta^{2^{\frac{k+1}{2}}}\left( u\Delta^2 + a^2 \Delta^{2^{\frac{k+1}{2}}} \right)  }{ \omega^2 \Delta^{2^{\frac{k+1}{2}+1}+2} } = \frac{a^2}{\Delta^2} + \frac{a^{2^{\frac{k+1}{2}}}}{\Delta^{2^{\frac{k+1}{2}}}}, $$
by Eq. \eqref{con1_eq6}, we get 
\begin{equation}
\label{con1_eq7}
    c = \left( \frac{a^2}{\Delta^2} + \frac{a^4}{\Delta^4} + \cdots + \frac{a^{2^{\frac{k-1}{2}}}}{\Delta^{2^{\frac{k-1}{2}}}}    \right) \omega \Delta^{2^{\frac{k+1}{2}} +1}
\end{equation}
or 
\begin{equation}
    \label{con1_eq8}
    c = \left( \frac{a^2}{\Delta^2} + \frac{a^4}{\Delta^4} + \cdots + \frac{a^{2^{\frac{k-1}{2}}}}{\Delta^{2^{\frac{k-1}{2}}}}    +1 \right) \omega \Delta^{2^{\frac{k+1}{2}} +1}.
\end{equation}
  Raising Eq. \eqref{con1_eq7} into its $q$-th power and simplifying it by $\Delta^q = \omega^2\Delta$ and $\omega^{2^\frac{k+1}{2}}=\omega^2$, we obtain
$$ c^q = \left(  \frac{\omega^2a^{2q}}{\Delta^2} + \frac{\omega a^{4q}}{\Delta^4} + \cdots + \frac{\omega a^{2^{\frac{k-1}{2}}q}}{\Delta^{2^{\frac{k-1}{2}}}} \right)\omega^2\Delta^{2^{\frac{k+1}{2}}+1}.$$
Moreover, $c^q=c\omega$ implying 
$$\frac{\omega^2a^{2q}}{\Delta^2} + \frac{\omega a^{4q}}{\Delta^4} + \cdots + \frac{\omega a^{2^{\frac{k-1}{2}}q}}{\Delta^{2^{\frac{k-1}{2}}}} + \frac{a^2}{\Delta^2} + \frac{a^4}{\Delta^4} + \cdots + \frac{a^{2^{\frac{k-1}{2}}}}{\Delta^{2^{\frac{k-1}{2}}}} =0.$$

Let $\lambda = \frac{a+\omega a^{q}}{\Delta}$. Then $$\lambda^q=\frac{a^{q}+\omega^2 a}{\omega^2 \Delta} = \lambda.$$
Moreover, we have $$\lambda^2 + \lambda^4 + \cdots + \lambda^{2^{\frac{k-1}{2}}} = 0,$$
which implies 
$$ \left(\lambda^2 + \lambda^4 + \cdots + \lambda^{2^{\frac{k-1}{2}}}\right) + \left(\lambda^2 + \lambda^4 + \cdots + \lambda^{2^{\frac{k-1}{2}}}\right)^{\frac{1}{2}} = \lambda + \lambda^{2^{\frac{k-3}{2}}} = 0.$$
Since $\gcd\left( 2^{\frac{k-3}{2}}-1, 2^{k}-1   \right)=1$, we can get $\lambda\in\gf_2$. Then $\lambda^2+\lambda^4+\cdots + \lambda^{2^{\frac{k-1}{2}}}=0$ and thus $c=0$ or $c=\omega \Delta^{2^{\frac{k+1}{2}}+1}$ by Eq. \eqref{con1_eq7} and Eq. \eqref{con1_eq8}. Contradiction! (Note that in this case, 
$c \neq (u^q\omega + u)(a^q+a\omega) = \omega \Delta^{2^{\frac{k+1}{2}}+1}$.)

    In conclusion, for any $a \in \gf_{q^2}$, Eq. (\ref{3.5}) has exactly one nonzero solution in $\gf_{q^2}$, and thus $f(x)$ is $2$-to-$1$.
\end{proof}

In the following, we give this section's final infinite class of $2$-to-$1$ mappings. Before that, we provide a lemma. 

\begin{Lemma}
\label{lemma_conj2}
    Let $k$ be an odd positive integer and $q=2^k$, $t\in\gf_q\backslash\gf_2$. Then the equation $x^3+(1+t)x+t+t^2=0$ has three solutions in $\gf_{q^2}$, i.e.,
    $$x_1 = \alpha+\alpha^2, x_2 = \alpha\omega + \alpha^2\omega^2, x_3 = \alpha\omega^2 + \alpha^2\omega,$$
    where $\alpha\in\gf_q$ with $\alpha^3=1+t$ and $\omega\in\gf_4\backslash\gf_2$. 
\end{Lemma}

\begin{proof}
    By Lemma \ref{cubics soulution}, we first consider the quadratic equation $y^2+(t+t^2)y+(1+t)^3=0$, i.e.,
    \begin{equation}
    \label{lemma_eq1}
        \left(\frac{y}{t+t^2}\right)^2 + \frac{y}{t+t^2} + \frac{(1+t)^3}{(t+t^2)^2} = 0.
    \end{equation}
    Note that 
    $$\frac{(1+t)^3}{(t+t^2)^2} = \frac{1+t}{t^2} = \frac{1}{t} + \frac{1}{t^2}.$$
    Thus Eq. \eqref{lemma_eq1} has a solution $y_1 = \frac{t+t^2}{t} = 1+t.$ Moreover, since $k$ is odd, the equation $x^3=y_1$ has a exactly one solution in $\gf_q$, denoted by $\alpha$. That is to say, $\alpha^3 = 1+t$. Furthermore, it is trivial that $x^3=y_1$ has three solutions in $\gf_{q^2}$, i.e, $\alpha, \alpha\omega,\alpha\omega^2$. Finally, by Lemma \ref{cubics soulution}, we can find the three solutions in $\gf_{q^2}$ of the equation $x^3+(1+t)x+t+t^2=0$ as follows:
      $$x_1 = \alpha+\alpha^2, x_2 = \alpha\omega + \alpha^2\omega^2, x_3 = \alpha\omega^2 + \alpha^2\omega.$$
\end{proof}

\begin{Th}
    \label{conj2}
    Let $k$ be an odd positive integer and $q=2^k$, $c \in \gf_{q^2}^*$ satisfies $c^{q-1}=\omega$ with $\omega \in \gf_{2^2} \backslash \gf_2$. Then $f(x)=cx+\tr_{q^2/q}\left(x^{2^{2k-2}+2^{k-1}}\right)$ is $2$-to-$1$ over $\gf_{q^2}$.
\end{Th}
\begin{proof}
    Let $g(x)=f\left(x^4\right)=cx^4+\tr_{q^2/q}\left(x^{2^{2k}+2^{k+1}}\right)=cx^4+\tr_{q^2/q}\left(x^{2q+1}\right)$. According to Lemma \ref{$2$-to-$1$}, it suffices to show that for any $a\in \gf_{q^2}$, the equation $$g(x+a)+g(a)=0,$$ i.e.,  
    \begin{eqnarray}\label{ini3.6}
        cx^4+a^2x^q+a^qx^2+x^{q+2}+a^{2q}x+ax^{2q}+x^{2q+1}=0
    \end{eqnarray}
    has two solutions in $\gf_{q^2}$.
    Let $y=x^q$. Plugging it into Eq. (\ref{ini3.6}), we get
    \begin{eqnarray}\label{3.6-2}
        cx^4+a^qx^2+a^{2q}x+a^2y+x^2y+ay^2+xy^2=0.
    \end{eqnarray}
    Computing the sum of Eq. (\ref{3.6-2}) and its $q$-th power, we obtain $y=c^{\frac{1-q}{4}}x$, that is $y=\omega^{-\frac{1}{4}}x = \omega^2x$. Plugging the above relation into Eq. \eqref{3.6-2}, we have $x=0$ or
    \begin{equation}
        \label{eq1} x^3+\frac{x^2}{c}+\frac{a^q+a\omega}{c}x+\frac{a^2\omega^2+a^{2q}}{c}=0.
    \end{equation}

    Let $x=z+c^{-1}$. Then Eq. \eqref{eq1} becomes
    \begin{eqnarray}
   \label{labubu}
        z^3+ \left(\frac{1}{c^2}+\frac{a^q+a\omega}{c}\right)z+\frac{a^q+a\omega}{c^2}+\frac{a^2\omega^2+a^{2q}}{c}=0.
    \end{eqnarray}

  Let $s=a^qc$, $t=s+s^q$. Then $t = a^qc+ac^q=(a^q+a\omega)c$ and Eq. \eqref{labubu} becomes
    \begin{equation}
        \label{eq2}
        z_1^3 + (1+t)z_1+t+t^2=0,
    \end{equation}
    where $z_1=cz$. 



    If $t=(a^q+a\omega)c=0$, i.e., $a=0$ or $a^{q-1}=\omega$, then $a=cu$ with $u\in\gf_q$. In this case, Eq. \eqref{eq2} becomes $z_1^3+z_1=0$, implying $z_1=0$ or $z_1=1$, i.e., $z=0$ or $z=c^{-1}$ and thus $x=c^{-1}$ or $x=0$. It is easy to check that in this case, $x=0,c^{-1}$ are indeed two solutions of Eq. \eqref{ini3.6}. 

    If $t=(a^q+a\omega)c=1$, then Eq. \eqref{eq2} becomes $z_1^3=0$, i.e., $z_1=0$ and then $x=c^{-1}$. It is also easy to check that in this case, $x=0,c^{-1}$ are indeed two solutions of Eq. \eqref{ini3.6}.  

    In the following, we assume that $t\in\gf_q\backslash\gf_2$. Then by Lemma \ref{lemma_conj2}, Eq. \eqref{eq2} has three solutions:
    $$z_1= \alpha+\alpha^2, \alpha\omega + \alpha^2\omega^2 ~\text{and}~\alpha\omega^2 + \alpha^2\omega,$$
    where $\alpha\in\gf_q$ with $\alpha^3=1+t$,
    and thus 
    \begin{equation}
    \label{eq3}
        x=c^{-1}z_1+c^{-1} = c^{-1}(\alpha+\alpha^2+1), c^{-1} (\alpha\omega + \alpha^2\omega^2 + 1) ~\text{and}~c^{-1}(\alpha\omega^2 + \alpha^2\omega + 1)
    \end{equation}
    are solutions of Eq. \eqref{eq1}. Note that the solutions of \eqref{3.6-2} satisfy the relation $x^q=\omega^2x$. It is easy to check that in the three solutions \eqref{eq3}, there is only one solution, i.e., $x=c^{-1}(\alpha+\alpha^2+1)$ that satisfies $x^q+\omega^2x$ and thus Eq. \eqref{ini3.6}  has only one nonzero solution in $\gf_{q^2}$. That is to say, Eq. \eqref{ini3.6} has two solutions, i.e., $x=0, c^{-1}(\alpha+\alpha^2+1)$ in $\gf_{q^2}$.

  In conclusion, for any $a\in\gf_{q^2}$, Eq. \eqref{ini3.6} has two solutions in $\gf_{q^2}$ and thus $f(x)$ is $2$-to-$1$. 
\end{proof}

\section{$2$-to-$1$ mappings of the form $cx^d+\tr_{q^l/q}(x^{d_1}+x^{d_2})$}\label{binomial}
This section focuses on constructing several $2$-to-$1$ mappings over the finite field $\gf_{q^l}$ of the form $cx^d+\tr_{q^l/q}(x^{d_1}+x^{d_2})$. The scope we search is as follows: $q=2^k$, $d_1,d_2 \in[1,q^l-2]$, $kl<14$, $c \in \gf_{q^l}^*$, $k,l \in \mathbb{N}^+$.
To narrow the search space, the following two additional conditions are imposed:
\begin{enumerate}[(1)]
	\item since \cite{charpin2009does} has already investigated the case where $k=1$, to avoid obtaining redundant results, it is assumed that $k>1$. 
	\item $d_1,d_2$ are the representative element of all positive integers less than $q^l-1$ under the cyclotomic equivalence. To prevent duplicate searches, it is assumed that $d_1<d_2$ and $\tr_{q^l/q}(x^{d_1}+x^{d_2}) \ne 0$.
        \item Regarding the range of $d$, only cases where $d$ within the range $[1,q^l-1]$ is a divisor of $q^l-1$ are considered according to Lemma \ref{divisor}.
\end{enumerate} 

Then we obtain all $2$-to-$1$ polynomials over $\gf_{q^l}$ of the form $cx^d+\tr_{q^l/q}(x^{d_1}+x^{d_2})$ with $q=2^k$, $d,d_1,d_2 \in[1,q^l-2]$, $kl<14$, $c \in \gf_{q^l}^*$ and $k,l \in \mathbb{N}^+$ in Table \ref{4-1}. The ``Reference" column in the table indicates
