\begin{Th}
	\label{q+1,2q+2}
	Let $k$ be an even positive integer and $l$ be odd. Then $f(x)=cx+\tr_{q^l/q}(x^{q+1}+x^{2q+2})$ is $2$-to-$1$ over $\gf_{q^l}$, where $q=2^k$, $c\in \gf_{q}^*$ with $\tr_{q}(c^{-1}+1)=1$.
\end{Th}
\begin{proof}
	According to Lemma \ref{$2$-to-$1$}, it suffices to show that for any $a\in \gf_{q^l}$, the equation $$f(x+a)+f(a)=0,$$ i.e.,
	\begin{eqnarray}\label{8}
		cx+\tr_{q^l/q}(x^{q+1}+x^qa+a^qx+x^{2q+2}+x^{2q}a^2+a^{2q}x^2)=0
	\end{eqnarray}
	has two solutions in $\gf_{q^l}$.

    According to Eq. (\ref{8}), we get $cx=\tr_{q^l/q}(x^{q+1}+x^qa+a^qx+x^{2q+2}+x^{2q}a^2+a^{2q}x^2)\in \gf_{q}$ and $x\in \gf_{q}$ since $c\in \gf_{q}^*$. 

    From Lemma \ref{trace}(4), $$x^{q+1}+\tr_{q^l/q}(a^q)x+\tr_{q^l/q}(a)x^q+x^{2q+2}+\tr_{q^l/q}(a^2)x^{2q}+\tr_{q^l/q}(a^{2q})x^2+cx=0,$$
	where $l$ is odd and $x\in \gf_{q}$.
	\\In case of $\tr_{q^l/q}(a+a^q)=0$, we get 
	\begin{eqnarray}\label{9}
		x^4+x^2+cx=0.
	\end{eqnarray}

    Thus $x=0$ and it suffices to prove that for any $a \in \gf_{q^l}$, the equation $x^3+x+c=0$ has one solution in $\gf_{q^l}^*$.

    According to Lemma \ref{cubic}, $f_1(x)=x^3+x+c$, $\tr_{q}(\frac{1}{c^2})\ne \tr_{q}(1)$ since $c\ne 0$ and $\tr_{q} (c^{-1}+1)=1$, then $f_1=(1,2)$. Therefore, Eq. (\ref{9}) has two solutions in $\gf_{q}$. Moreover, Eq. (\ref{9}) has two solutions in $\gf_{q^l}$, $f(x)$ is $2$-to-$1$ over $\gf_{q^l}$.
\end{proof}
\begin{Th}
\label{4.2}
	Let $l$ be an odd positive integer and $q=2^k$, $k \in \mathbb{N}^+$, $c \in \gf_{q}\backslash \{0,1\}$. Then
	\begin{enumerate}[1)]
		\item $f(x)=cx+\tr_{q^l/q}\left(x^{q+1}+x^{\frac{q^2+q}{2}}\right)$;\label{q+1,q^2+q/2}
		\item $f(x)=cx+\tr_{q^l/q}\left(x^{\frac{q^2+q}{2}}+x^{\frac{q^2+q}{4}}\right)$ \label{q^2+q/2+q^2+q/4}
	\end{enumerate}
	are $2$-to-$1$ over $\gf_{q^l}$. 
\end{Th}
\begin{proof}
In the first (resp. second) function, we give the substitution $x \mapsto x^2$ (resp. $x^4$). Since the proof techniques for these cases are analogous, we present a detailed demonstration for the first case as a representative example.

    Let $g(x)=f(x^2)=cx^2+\tr_{q^l/q}(x^{2q+2}+x^{q^2+q})$. It suffices to prove that for any $d\in \gf_{q^l}$, the equation $g(x)=d$ has 0 or 2 solutions in $\gf_{q^l}$. Then we consider the solution of the following equation, 
	\begin{eqnarray}\label{10}
		cx^2+\tr_{q^l/q}(x^{2q+2}+x^{q^2+q})=d.
	\end{eqnarray}

    Let $u=cx^2+d=\tr_{q^l/q}(x^{q^2+q})+\tr_{q^l/q}(x^{2q+2})\in \gf_{q}$. Then $x=\left(\frac{u+d}{c}\right)^{\frac{1}{2}}$ due to $c\ne0$. Moreover, since $u \in \gf_{q}$ and $c \in \gf_{q}\verb|\|\{0,1\}$, we have $$x^{q^2+q}=\left(\frac{u+d}{c}\right)^{\frac{q^2+q}{2}}=\frac{(u^2+(d^{q^2}+d^q)u+d^{q^2+q})^\frac{1}{2}}{c},$$ $$x^{2q+2}=\left(\frac{u+d}{c}\right)^{q+1}=\frac{u^2+(d^{q^2}+d)u+d^{q+1}}{c^2}.$$

    Plugging the above two equations into Eq. (\ref{10}), we get
	\begin{eqnarray*}
		u&=&\tr_{q^l/q}\left(\frac{u^2+u\left(d+d^q\right)+d^{q+1}}{c^2}+\frac{\left(u^2+\left(d^{q^2}+d^q\right)u+d^{q^2+q}\right)^\frac{1}{2}}{c}\right)\\
		&=&\frac{u^2}{c^2}+\tr_{q^l/q}\left(d+d^q\right)\frac{u}{c^2}+\frac{\tr_{q^l/q}\left(d^{q+1}\right)}{c^2}+\frac{u}{c}+\left(\tr_{q^l/q}\left(d^{q^2}+d^q\right)\right)^\frac{1}{2}\frac{u^\frac{1}{2}}{c}+\frac{\left(\tr_{q^l/q}\left(d^{q^2+q}\right)\right)^\frac{1}{2}}{c},
	\end{eqnarray*}
	where the second equality holds due to Lemma \ref{trace}(4) and $l$ being odd. Note that for any $d \in \gf_{q^l}$, it is clear that $\tr_{q^l/q}(d+d^q)=0$ and thus the above equation becomes 
	$$u=\frac{u^2}{c^2}+\frac{\tr_{q^l/q}\left(d^{q+1}\right)}{c^2}+\frac{u}{c}+\frac{\left(\tr_{q^l/q}\left(d^{q^2+q}\right)\right)^\frac{1}{2}}{c},$$
	that is 
	\begin{eqnarray}\label{11}
		u^2+(c^2+c)u+c\left(\tr_{q^l/q}\left(d^{q^2+q}\right)\right)^{\frac{1}{2}}+\tr_{q^l/q}(d^{q+1})=0
	\end{eqnarray}

    Since $c \notin \{0,1\}$, Eq. (\ref{11}) has 0 or 2 solutions in $\gf_{q}$. Hence $g(x)=d$ has 0 or 2 solutions in $\gf_{q^l}$, that is $g(x)$ is $2$-to-$1$ over $\gf_{q^l}$, $f(x)$ is $2$-to-$1$ over $\gf_{q^l}$.
\end{proof}
\begin{Th}
	\label{6,2q+4}
	Let $k$ be an odd positive integer and $q=2^k$, $c \in \gf_{q^2}$ satisfies $c^{q-1}=\omega$, where $\omega^3=1$. Then $f(x)=cx+\tr_{q^2/q}(x^6+x^{2q+4})$ is $2$-to-$1$ over $\gf_{q^2}$.
\end{Th}
\begin{proof}
	According to Lemma \ref{$2$-to-$1$}, it suffices to show that for any $a \in \gf_{q^2}$, the equation $$f(x+a)+f(a)=0,$$ i.e., 
	\begin{eqnarray}\label{12}
		cx+\tr_{q^2/q}((x+a)^6+a^6+(x+a)^{2q+4}+a^{2q+4})=0
	\end{eqnarray}
	has two solutions in $\gf_{q^2}$.

     Let $y=x^{2q}$, $b=a^{2q}$. From Eq. (\ref{12}), we get 
	\begin{eqnarray}\label{13}
		\left(a^2+a^{2q}\right)x^4+\left(a^4+a^{4q}\right)x^2+cx+x^4y+x^4b+a^4y+x^2y^2+x^2b^2+a^2y^2=0.
	\end{eqnarray}

     According to Eq. (\ref{12}), we get $cx=\tr_{q^2/q}((x+a)^6+a^6+(x+a)^{2q+4}+a^{2q+4})\in \gf_{q}$. Then $y=c^{2(1-q)}x^2$, implying $y=\omega x^2$.
    Then from Eq. (\ref{13}),$$\left(a^2+a^{2q}\right)x^4+\left(a^4+a^{4q}\right)x^2+\left(\omega+\omega^2\right)x^6+\left(a^2\omega^2+b\right)x^4+\left(a^4\omega+b^2\right)x^2+cx=0.$$

    According to the properties of cubic primitive roots $\omega^2+\omega+1=0$, the above equation becomes $$x^6+\left(a^2\omega^2+b\right)x^4+\left(a^4\omega+b^2\right)x^2+cx=0.$$

    Obviously $x=0$, it only need to prove for any $a\in \gf_{q^2}$, the equation 
	\begin{eqnarray}\label{14}
		x^5+\left(a^2\omega^2+b\right)x^3+\left(a^4\omega+b^2\right)x+c=0
	\end{eqnarray}
	has one solution in $\gf_{q^2}^*$.

    We notice that $x^5+\left(a^2\omega^2+b\right)x^3+\left(a^4\omega+b^2\right)x=D_5\left(x,a^2\omega^2+b\right)$ is Dickson polynomial of degree 5. Recalling that $k$ is odd, then $\mathrm{gcd}(5,q^2-1)=1$. From Lemma \ref{gcd}, $D_5(x,a^2\omega^2+b)$ permutes $\gf_{q}$. That is, Eq. (\ref{14}) only has one solution in $\gf_{q}$, and the solution is not 0 since $c \ne 0$. Therefore, the Eq. (\ref{12}) has two solutions in $\gf_{q^2}$ and $f(x)$ is $2$-to-$1$ over $\gf_{q^2}$.
\end{proof}
\begin{Th}
\label{4.4}
	Let $k$ and $l$ be odd positive integers and $q=2^k$, $c \in \gf_{q}\verb|\|\{0,1\}$. Then
	\begin{enumerate}[1)]
		\item $f(x)=cx+\tr_{q^l/q}\left(x^6+x^{\frac{q^2+q}{2}}\right)$;\label{6,q^2+q/2}
		\item $f(x)=cx+\tr_{q^l/q}\left(x^{4q+2}+x^{\frac{q^2+q}{2}}\right)$;\label{4q+2,q^2+q/2}
		\item $f(x)=cx+\tr_{q^l/q}\left(x^{2q+4}+x^{\frac{q^2+q}{2}}\right)$ \label{2q+4,q^2+q/2}
	\end{enumerate}
	are $2$-to-$1$ over $\gf_{q^l}$. 
\end{Th}
\begin{proof}
Since the proof techniques for these cases are analogous, we present a detailed demonstration for the first case as a representative example.

    According to Lemma \ref{$2$-to-$1$}, it suffices to show that for any $a \in \gf_{q^l}$, the equation $$f(x+a)+f(a)=0,$$ i.e.,
	\begin{eqnarray}\label{15}
		cx+\tr_{q^l/q}(x^6+a^2x^4+a^4x^2+(x^{q^2+q}+x^{q^2}a^q+a^{q^2}x^q)^\frac{1}{2})=0
	\end{eqnarray}
	has two solutions in $\gf_{q^l}$. 

    According to Eq. (\ref{15}), we get $$cx=\tr_{q^l/q}(x^6+a^2x^4+a^4x^2+(x^{q^2+q}+x^{q^2}a^q+a^{q^2}x^q)^\frac{1}{2})\in \gf_{q}$$ and then $x \in \gf_{q}$ since $c \in \gf_{q^l}^*$. 

    From Lemma \ref{trace}(4), $$x^6+\tr_{q^l/q}(a^2)x^4+\tr_{q^l/q}(a^4)x^2+(x^2+\tr_{q^l/q}(a^q)x+\tr_{q^l/q}(a^{q^2})x)^\frac{1}{2}+cx=0,$$
	where $l$ is odd and $x\in \gf_{q}$.

    In case of $\tr_{q^l/q}(a+a^q)=0$, we get 
	\begin{eqnarray}\label{16}
		x^6+\tr_{q^l/q}(a^2)x^4+\tr_{q^l/q}(a^4)x^2+x+cx=0.
	\end{eqnarray}

    Thus $ x=0$ or 
	\begin{eqnarray}\label{17}
		x^5+\tr_{q^l/q}(a^2)x^3+\tr_{q^l/q}(a^4)x+1+c=0.
	\end{eqnarray}

    We notice that $$x^5+\tr_{q^l/q}(a^2)x^3+\tr_{q^l/q}(a^4)x=D_5(x,\tr_{q^l/q}(a^2))$$ is a Dickson polynomial of degree 5. Recalling that $k$ is odd, then $\mathrm{gcd}(5,q^2-1)=1$. From Lemma \ref{gcd}, $D_5(x,\tr_{q^l/q}(a^2))$ permutes $\gf_{q}$. That is, Eq. (\ref{17}) has only one solution in $\gf_{q}$ and the solution is non-zero since $c \notin \{0,1\}$. Therefore, the Eq. (\ref{15}) has two solutions in $\gf_{q^l}$ and $f(x)$ is $2$-to-$1$ over $\gf_{q^l}$.
\end{proof}
