\begin{Th}\label{ex}
    Let $l$ be an odd positive integer, $q=2^k$, $k \in \mathbb{N}$, $n=kl$,  $c\in\mathbb{F}_q^\ast$, 
	\begin{enumerate}[1)]
		\item $f(x)=cx+\tr_{q^l/q}(x^{q+1})$;
		\item $f(x)=cx+\tr_{q^l/q}(x^{2q+2})$, where $k$ is odd; 
		\item $f(x)=cx+\tr_{q^l/q}(x^{q^2+1})$. 
	\end{enumerate} Define linear code $C_f$ as in (\ref{cf}) is a $[2^n-1, n+k,2^{n-1}-2^{\frac{n+k}{2}-1}]$ binary linear code with weight distribution in Table \ref{code1}.
\end{Th}
\begin{proof}
    The linear codes constructed from these three functions have the same weight distribution. Now we take the first one $f(x)=cx+\tr_{q^l/q}(x^{q+1})$ as an example to construct the linear code $C_f$.
    We compute the Walsh transforms $W_f(a.b)$ defined as in (\ref{walsh}). 
    \begin{eqnarray*}
    \tr_{2^n}(ax+bf(x))
    &=&\tr_{2^n}((a+bc)x+b\tr_{2^n/2^k}(x^{q+1}))\\
    &=&\tr_{2^n}(ax+bcx+b(x^{q+1}+x^{(q+1)q}+\cdots+x^{(q+1)q^{l-1}}))\\
    &=&\tr_{2^n}(ax+bcx+bx^{q+1}+(b^{\frac{1}{q}}x^{q+1})^q+\cdots+(b^{\frac{1}{q^{l-1}}}x^{q+1})^{q^{l-1}})\\
    &=&\tr_{2^n}(ax+bcx+(b+b^\frac{1}{q}+\cdots+b^\frac{1}{q^{l-1}})x^{q+1})\\
    &=&\tr_{2^n}((a+bc)x+\tr_{2^n/2^k}(b^\frac{1}{q^{l-1}})x^{q+1})\\
    &=&\tr_{2^n}((a+bc)x+\tr_{2^n/2^k}(b)x^{q+1}).
    \end{eqnarray*}
    Then we have the Walsh transform 
     $$W_f(a,b)=\sum_{x\in \gf_{2^n}}(-1)^{\tr_{2^n}(ax+bf(x))}=\sum_{x\in \gf_{2^n}}(-1)^{\tr_{2^n}((a+bc)x+\tr_{2^n/2^k}(b)x^{q+1})}.$$

When $\tr_{2^n/2^k}(b)=0$,
$$W_f(a,b)=\sum_{x\in \gf_{2^n}}(-1)^{\tr_{2^n}(ax)}=\begin{cases}
2^n &a+bc=0 ,\\
0 &a+bc\ne0.
\end{cases}
$$

When $\tr_{2^n/2^k}(b)\ne 0$, $\varphi_{a,b}(x)=\tr_{2^n}((a+bc)x+\tr_{2^n/2^k}(b)x^{q+1})$, the bilinear form of $\varphi_{a,b}(x)$ is given by
\begin{eqnarray*}
    B_{\varphi_{a,b}}(x,y)
    &=&\varphi_{a,b}(x+y)+\varphi_{a,b}(x)+\varphi_{a,b}(y)\\
    &=&\tr_{2^n}(\tr_{2^n/2^k}(b)(x+y)^{q+1}+\tr_{2^n/2^k}(b)x^{q+1}+\tr_{2^n/2^k}(b)y^{q+1})\\
    &=&\tr_{2^n}(\tr_{2^n/2^k}(b)x^qy+\tr_{2^n/2^k}(b)xy^q)\\
    &=&\tr_{2^n}((\tr_{2^n/2^k}(b)y+(\tr_{2^n/2^k}(b))^qy^{q^2})x^q).
\end{eqnarray*}

Its kernel is given by 
\begin{eqnarray*}
    V_{\varphi_{a,b}}
    &=&\{y \in \gf_{2^n}: B_{\varphi_{a,b}}(x,y)=0 ,\forall x \in \gf_{2^n}\}\\
    &=&\{y \in \gf_{2^n}: \tr_{2^n/2^k}(b)y+(\tr_{2^n/2^k}(b))^qy^{q^2}=0\},
\end{eqnarray*}
the number of solutions are $\gcd(q^2-1,q^l-1)+1=q=2^k$, then the dimension of $V_{\varphi_{a,b}}$ is $d=\log_2{(\gcd(q^2-1,q^l-1)+1)}=k$.

From Lemma \ref{qua}, we have
$$W_f(a,b)
\begin{cases}
\pm2^{\frac{n+k}{2}}, & \text{if $\varphi_{a,b}$ vanishes on $V_{\varphi_{a,b}}$}, \\
0, & \text{otherwise}.  
\end{cases}$$

Generally, $W_f(a,b)=\{2^n,0,\pm 2^{\frac{n+k}{2}} \}$. Let their corresponding frequencies be $X_0, X_1, X_2, X_3$.
When $a+bc=0$ and $\tr_{2^n/2^k}(b)=0$, $W_f(a,b)=2^n$. The number of solutions of $\tr_{2^n/2^k}(b)=0$ in $\gf_{2^n}$ is $2^{n-k}$ and $b=\frac{a}{c}\in \gf_{2^n}$, then the $X_0=2^{n-k}$. We have  
$$\begin{cases}
    2^{n-k}+X_1+X_2+X_3=2^{2n}\\
    2^{2n-k}+2^{\frac{n+k}{2}}X_2-2^{\frac{n+k}{2}}X_3=2^{2n}\\
    2^{3n-k}+2^{n+k}X_2+2^{n+k}X_3=2^{3n}.
\end{cases}
$$
Then $$\begin{cases}
    X_0=2^{n-k}\\
    X_1=2^{2n}+2^{2n-2k}-2^{2n-k}-2^{n-k}\\
    X_2=2^{\frac{3n-k}{2}-1}-2^{\frac{3n-3k}{2}-1}+2^{2n-k-1}-2^{2n-2k-1}\\
    X_3=2^{2n-k-1}-2^{2n-2k-1}-2^{\frac{3n-k}{2}-1}+2^{\frac{3n-3k}{2}-1}.

\end{cases}
$$
The weight distribution of the linear code $C_f$ is entirely determined by the Walsh spectrum of $f$. If a value 
$W_f(a,b)$ appears $X$ times in the Walsh spectrum of $f$, then the number of codewords in $C_f$ with Hamming weight $2^{n-1}-\frac{1}{2}W_f(a,b)$ is $\frac{X}{X_0}$. Therefore, in the linear code $C_f$, the Hamming weight of a codeword $c_{a,b}$ satisfies $wt(c_{a,b})=\{0,2^{n-1},2^{n-1}-2^{\frac{n+k}{2}-1},2^{n-1}+2^{\frac{n+k}{2}-1}\}$. The weight distribution is shown in Table \ref{code1}...
\end{proof}
