\subsection{Process-Variation Aware Adaptation of Particle Swarm Optimization (PSO) Algorithm}

The optimization problem implemented in this flow is to minimize the power consumption of the PLL circuit using the locking time as a design constraint. The process aware optimization of the circuit involves minimizing the mean $\mu$ and standard deviation $\sigma$ of the optimal power consumption. As a specific example, the optimization function can be expressed as follows:
\begin{equation}
\text{Minimize}[{\mu }_{pwr} + 3 {\sigma }_{pwr}],
\end{equation}
while subjected to locking time constraint. The PSO algorithm for the PLL is shown in Algorithm \ref{Alg:PSO_Algorithm}. Fig. \ref{Fig:algo_Flow} presents an illustration of the algorithm.


\begin{algorithm}[htbp]
\caption{Particle Swarm Optimization of PLL over the Metamodels \cite{Mohanty_ISQED_2015}.}
\label{Alg:PSO_Algorithm}
%\DontPrintSemicolon
\KwIn{Tuning parameter set $X$, Bootstrapped Kriging metamodels, Tuning parameter ranges.}
\KwOut{$X=(x_1, x_2,...,x_n)$ parameter set with optimized statistical performance;}
\Begin{
\SetKwHangingKw{HData}{SET:}
\HData{$N$, number of particles}
\HData{Max$_{iteration}$, counter $\longleftarrow$ 0}
\HData{local best $l_{x_i} \longleftarrow$ current position}
\HData{global best $g_{x_i} \longleftarrow$ current position}
\SetKwHangingKw{HData}{Initialize:}
\HData{weight for swarm effect $\varrho$}
\HData{velocity for swarm effect $w$}
\While{counter $<$ Max$_{iteration}$}{
   \ForEach{N}{
%   \SetKwHangingKw{HData}{Perform:}
   Monte Carlo analysis over metamodels with nominal $x_i$\;
   $v_i$ = $wv_i$ + $\varrho_p\tau_p(lx_i-x_i)$ + $\varrho_g\tau_g(gx_i-x_i)$\;
   $x_i$ $\leftarrow$  $x_i$ + $v_i$\;
   \If{$x_i$ $<$ $l_{x_i}$}{
  	  $l_{x_i}$ $\leftarrow$ $x_i$\;	
      \If{$l_{x_i}$ $<$ $g_{x_i}$}{
        $g_{x_i}$ $\leftarrow$ $l_{x_i}$\;
        }
     }
  }
}
}
\KwResult{Parameter set $X$ with minimized $\mu$, $\sigma$;}
\end{algorithm}


