    Now we complete the finite sequence $(Q_k)_{k=1,\dots,\tilde{\mathcal{K}}}$ with further cubes $(Q_k)_{k=\tilde{\mathcal{K}}+1,\dots,\mathcal{K}}$, $\mathcal{K}\lesssim_{\,d} n^{d} $, of side length $n^{-1}$ from the uniform grid such that
\begin{equation*}
	\bigcup\limits_{k=1}^\mathcal{K} Q_k = \bigcup\limits_{k=1}^{\tilde{\mathcal{K}}} \tilde{Q}_k.
\end{equation*} 

The set $(Q_k)_{k=1,\dots,\mathcal{K}}$ now fulfills \ref{Lemma_Approximation_step_functions_enum_2} and \ref{Lemma_Approximation_step_functions_enum_3}. Still, \ref{Lemma_Approximation_step_functions_enum_4} and \ref{Lemma_Approximation_step_functions_enum_5} remain to be shown. First, we consider $p<\infty$. For $i\in\{1,\dots,n\}$ and $k\in\{1,\dots,\tilde{\mathcal{K}}\}$ there is a constant $\tilde{c}_{i,k}$ according to \cref{Jackson for r_1=r_2=1 lemma} which allows us to estimate
\begin{align}\label{Lemma_Approximation_step_functions_proof_2}
	\int\limits_{I_{i}\times (\tilde{Q}_k\cap D)} | f(t,\bm{x})- \tilde{c}_{i,k}|^p\,d(t,\bm{x}) &\lesssim_{\,p} \frac{1}{|I_i|}\int\limits_{\{|h|\le |I_{i}|\}} \|\Delta^1_{h,t}\|^p_{L_p((I_i)_{1,h}\times (\tilde{Q}_k\cap D))}\,dh 
	\\ & \ \ \ + \frac{1}{|\tilde{Q}_k\cap D|}\int\limits_{\{|\bm{h}|\le \diam(\tilde{Q}_k\cap D)\}} \|\Delta^1_{\bm{h},\bm{x}}\|^p_{L_p(I_i\times (\tilde{Q}_k\cap D)_{1,\bm{h}})}\,d\bm{h}	\notag	
	\\&\le \frac{1}{|I_i|}\int\limits_{\{|h|\le |I_i|\}} \|\Delta^1_{h,t}\|^p_{L_p((I_i)_{1,h}\times (\tilde{Q}_k\cap D))}\,dh \notag
	\\ & \ \ \ + \frac{1}{|\tilde{Q}_k\cap D|}\int\limits_{\{|\bm{h}|\le 3n^{-1}\sqrt{d}\}} \|\Delta^1_{\bm{h},\bm{x}}\|^p_{L_p(I_i\times (\tilde{Q}_k\cap D)_{1,\bm{h}})}\,d\bm{h}.\notag
\end{align}




