\title{Iterative Resolution of Prompt Ambiguities Using a Progressive Cutting-Search Approach}


\titlerunning{Resolution of Prompt Ambiguities Using a Pruning Approach}

\author{Fabrizio Marozzo\inst{1} \orcidID{0000-0001-7887-1314}} 

\authorrunning{F. Marozzo}

\institute{University of Calabria, Italy\\
\email{fmarozzo@dimes.unical.it}
